  },
  Event_116372_Name = {
    Text = "Авидья"
  },
  Event_116373_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_116373_Desc = {
    Text = "Ты нашёл сокровище."
  },
  Event_116373_Name = {
