  },
  Event_116429_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_116429_Desc = {
    Text = "Вы активировали случайное событие 3."
  },
  Event_116429_Name = {
    Text = "Случайное событие 3"
  },
  Event_116430_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_116430_Desc = {
    Text = "Вы активировали случайное событие 1."
  },
  Event_116430_Name = {
    Text = "Случайное событие 1"
  },
  Event_116431_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_116431_Desc = {
    Text = "Вы активировали случайное событие 2."
  },
  Event_116431_Name = {
    Text = "Случайное событие 2"
  },
  Event_117279_ChoiceDesc1 = {
    Text = "[Ты когда-то жаждал невинности]Положить 3 карты «(Skill.Arg1)» в колоду."
  },
  Event_117279_Desc = {
    Text = "\nНа уровне моря поднимается тонкий белый туман, окутывая всё в тёмную дымку.\nПреодолевая границы жизни и смерти, расстояние между дверью и внешним миром, вы видите фигуру дамы с зонтиком, которая стоит на фоне света.\nВремя, проведённое с ней, уже прошло, как и её хрупкая, но яркая молодость.\nВ ожидании призрачного восхода солнечного диска, туман разбивается на ничто, её силуэт колеблется и превращается в лёгкие иллюзии, шлёт вам безмолвное прощание."
  },
  Event_117279_Name = {
    Text = "Фантом Мёрфи"
  },
  Event_117280_ChoiceDesc1 = {
    Text = "[Вы когда-либо жаждали невинности]выберите 2 карты и наделите их гравировкой «Глубинное эхо»."
  },
  Event_117280_Desc = {
    Text = "\nНа уровне моря поднимается тонкий белый туман, окутывая всё в тёмную дымку.\nПреодолевая границы жизни и смерти, расстояние между дверью и внешним миром, вы видите фигуру дамы с зонтиком, которая стоит на фоне света.\nВремя, проведённое с ней, уже прошло, как и её хрупкая, но яркая молодость.\nВ ожидании призрачного восхода солнечного диска, туман разбивается на ничто, её силуэт колеблется и превращается в лёгкие иллюзии, шлёт вам безмолвное прощание."
  },
  Event_117280_Name = {
    Text = "Фантом Мёрфи"
  },
  Event_118414_ChoiceDesc1 = {
    Text = "\"три точки\""
  },
  Event_118414_ChoiceDesc2 = {
    Text = "\"шесть часов\""
  },
  Event_118414_ChoiceDesc3 = {
    Text = "\"одна точка\""
  },
  Event_118414_Desc = {
    Text = "Кубики закрутились, издавая глухое жужжание.\nКогда они остановятся?\nТы не знаешь, но ты должен дать Лечение."
  },
  Event_118414_Name = {
    Text = "Авантюра судьбы"
  },
  Event_118415_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118415_Desc = {
    Text = "Твой отклик делает «небо» ещё нежнее.\nОно легко касается поцелуем твоего лба.\nА затем на твоём лбу расцветает морская пена."
  },
  Event_118415_Name = {
    Text = "Объятия океана"
  },
  Event_118416_ChoiceDesc1 = {
    Text = "[Погрузиться в грёзы] Выбрать 1 Командную карту из 3 и получить Гриф: «(EnchantConfig.Arg1)», заразить «(Skill.Arg2)»"
  },
  Event_118416_ChoiceDesc2 = {
    Text = "[Удержание рассудок] За каждого пробуждённого с уровнем безумия 50 и выше получить 15 чёрных печатей"
  },
  Event_118416_ChoiceDesc3 = {
    Text = "[Уйти силой] Выбрать гравировку из 3 вариантов"
  },
  Event_118416_Desc = {
    Text = "Возможно, долгие сражения вызвали у тебя помутнение, а может, твой мозг просто предал твоё тело.\nНекое чувство невесомости возникло в твоём сознании.\nВ одно мгновение твой разум превратился в калейдоскоп — яркий, пёстрый, мерцающий всеми цветами радуги.\nБесчисленные вдохновения, наваждения и безумные фантазии хлынули в мозг, заполняя каждый уголок его извилин.\nЕсли так продолжится, твою голову скоро разорвёт от всего этого хаоса."
  },
  Event_118416_Name = {
    Text = "Калейдоскоп разума"
  },
  Event_118417_ChoiceDesc1 = {
    Text = "[Вступить в игру]заражает «(Skill.Arg1)», вступая в азартную игру"
  },
  Event_118417_ChoiceDesc2 = {
    Text = "\"Ладно, забудем\" получено 25 чёрных печатей"
  },
  Event_118417_Desc = {
    Text = "В мгновение помутнения твоё сознание пронеслось сквозь слои тумана и рассеялось в неизвестном пространстве.\nДва кубика были брошены перед тобой, но неведомое существо, насильно притащившее тебя сюда, так и не показалось.\nТы мог лишь слышать его хаотичный голос, доносящийся отовсюду.\n«Хочешь вернуться? Тогда сыграем партию.»\n«Поставь свою жизнь на кон и сразись с судьбой.»"
  },
  Event_118417_Name = {
    Text = "Авантюра судьбы"
  },
  Event_118418_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118418_Desc = {
    Text = "Трансцендентные переживания всегда мимолётны. Они приходят беззвучно и исчезают внезапно.\nНо по крайней мере твоя голова всё ещё на месте и не взорвалась по-настоящему."
  },
  Event_118418_Name = {
    Text = "Калейдоскоп разума"
  },
  Event_118419_ChoiceDesc1 = {
    Text = "\"Покинуть\" получить серебряное создание \"(RelicConfig.Arg1)\""
  },
  Event_118419_Desc = {
    Text = "Ты не проиграл, но и не выиграл — результат ни хорош, ни плох.\n«Ничья…»\nНеизвестное существо вздохнуло, но в его голосе не слышалось сожаления.\n«Какое приятное развлечение.»"
  },
  Event_118419_Name = {
    Text = "Авантюра судьбы"
  },
  Event_118420_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118420_Desc = {
    Text = "Постепенно безумные мелодии в твоих ушах стали гармоничными и священными.\nТы наконец прозрел и понял, почему это называется «Совершенным гимном».\nПотому что он действительно «безупречен»."
  },
  Event_118420_Name = {
    Text = "«Совершенный» гимн"
  },
  Event_118421_ChoiceDesc1 = {
    Text = "[Восприятие мозга]Выберите 1 Карту команды из 3 для получения гравировки: \"(EnchantConfig.Arg1)\""
  },
  Event_118421_ChoiceDesc2 = {
    Text = "[Ощутить душу]Заразить «(Skill.Arg1)», провести повторную гравировку, до 2 раз"
  },
  Event_118421_Desc = {
    Text = "Первая клетка человека — это его собственная оболочка.\nВ этой клетке-оболочке мозг — последняя и самая важная темница.\n«Милый, ты думаешь, что раз ты жив и ещё дышишь, то в безопасности?»\nКогда твой мозг предаёт твою душу, ты познаёшь самую мучительную пытку на свете.\nИ эта пытка будет сопровождать тебя всю жизнь."
  },
  Event_118421_Name = {
    Text = "Клетка разума"
  },
  Event_118422_ChoiceDesc1 = {
    Text = "[Коснуться бабочек] Удалить 2 карты"
  },
  Event_118422_ChoiceDesc2 = {
    Text = "[Прогнать бабочек]Получить проклятое создание \"(RelicConfig.Arg1)\", заразиться \"(Skill.Arg2)\""
  },
  Event_118422_ChoiceDesc3 = {
    Text = "\"Покинуть\"Вы получаете Arg1 чёрную печать"
  },
  Event_118422_Desc = {
    Text = "В глубинах моря нет бабочек. Это девушка, заточённая в комнате, вообразила этих существ.\nОни так прекрасны, свободно порхают в воздухе.\n«Если бы… если бы я тоже могла, как они, улететь отсюда…»\nОдна Глава о бабочке издала всхлип, но этот звук утонул в бесчисленном шелесте крыльев, утонул в стрёкоте печатной машинки — едва различимый."
  },
  Event_118422_Name = {
    Text = "Душа порхает, как Глава о бабочке"
  },
  Event_118423_ChoiceDesc1 = {
    Text = "[Перерезать верёвку]заражает«(Skill.Arg1)», получает Проклятая реликвия«(RelicConfig.Arg2)»"
  },
  Event_118423_ChoiceDesc2 = {
    Text = "[Развязать его]заражается дважды«(Skill.Arg1)», получает Серебряная реликвия«(RelicConfig.Arg2)»и«(RelicConfig.Arg3)»"
  },
  Event_118423_ChoiceDesc3 = {
    Text = "[Помочь ему освободиться]получает Серебряная реликвия«(RelicConfig.Arg1)»"
  },
  Event_118423_Desc = {
    Text = "«Говорят, бесконечные желания — это Огромная Огромная сила, движущая человека вперёд.»\n«Но когда это желание становится настолько сильным, что его нельзя ни игнорировать, ни отсечь, я лишь чувствую, как порождённое мной самим желание превращается в клетку, заточившую меня.»\nИз темноты донёсся обессиленный голос. Ты не видишь лица говорящего — лишь пару связанных рук.\n«Эти желания питаются моим страхом, трусостью, надеждой и болью, а затем лишь усиливают мои желания.»\nОбессиленный голос издал последнюю мольбу.\n«Я готов отдать всё! Добрый человек, спаси меня… или подари мне избавление…»"
  },
  Event_118423_Name = {
    Text = "Оковы желания"
  },
  Event_118424_ChoiceDesc1 = {
    Text = "[Восприятие мозга]Выберите 1 Карту команды из 3 для получения гравировки: \"(EnchantConfig.Arg1)\""
  },
  Event_118424_Desc = {
    Text = "Ты чувствуешь, как твой мозг дёрнулся.\n«Есть ли в этом какой-то особый смысл?»\nТы спрашиваешь себя, но мозг безмолвствует.\nНе каждый вопрос, обращённый к самому себе, получает Лечение."
  },
  Event_118424_Name = {
    Text = "Клетка разума"
  },
  Event_118425_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118425_Desc = {
    Text = "Ты старался всплыть, и, наконец, выскочил на поверхность．\nВоздух с морским солёным запахом ворвался в твои лёгкие, напоминая, что ты не выбрался из опасности.\nНо ты знаешь, настоящее небо прямо над твоей головой.\nКак истина, которая никогда не будет затмеваться мягкими ложными словами."
  },
  Event_118425_Name = {
    Text = "Объятия океана"
  },
  Event_118426_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118426_Desc = {
    Text = "В тот миг, когда ты коснулся верёвки желания, жгучая боль поднялась из глубин твоей души.\nТвой Страх, трусость, надежда, боль — всё хлынуло наружу, превращаясь в пропитанные кровью верёвки, сковавшие твои руки.\nВ этот момент ты услышал злорадное ликование того голоса.\n«Добрый человек, ты получишь награду… и, конечно, проклятие.»"
  },
  Event_118426_Name = {
    Text = "Оковы желания"
  },
  Event_118427_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118427_Desc = {
    Text = "Твоё прикосновение заставило бабочек задрожать.\nС момента своего рождения они никогда не испытывали такого нежного обращения.\nБабочки, охваченные растерянностью, даже забыли, как летать.\nИ тогда бесчисленные бабочки упали, обнажив печатную машинку, прежде скрытую за множеством крыльев.\nЭто бедное создание, уже лишённое жизни, последним усилием напечатало два слова: «Свобода»."
  },
  Event_118427_Name = {
    Text = "Душа порхает, как Глава о бабочке"
  },
  Event_118428_ChoiceDesc1 = {
    Text = "[Приготовиться к бою] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_118428_ChoiceDesc2 = {
    Text = "[Попытаться обойти] получить 25 чёрных печатей"
  },
  Event_118428_Desc = {
    Text = "В глубинах моря, куда ниспадает звёздный Погоня за светом, ступающие по морю затаились на тысячи лет.\nБескрайние воды были свидетелями их безумия, их терпения, а также их самой истовой веры в божество.\nНикто не в силах помешать великому пришествию божества.\nВсякий, кто встанет на пути, обратится в Пепел в гневе ступающих по морю."
  },
  Event_118428_Name = {
    Text = "Ожидание под звёздами"
  },
  Event_118429_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118429_Desc = {
    Text = "Ты инстинктивно зажал уши.\nНевероятно, но музыка из глубин души исчезла.\nКонечно, лишь на время."
  },
  Event_118429_Name = {
    Text = "Кощунственная мелодия"
  },
  Event_118430_ChoiceDesc1 = {
    Text = "[Вспомнить прошлое] получить выбрать 1 из 3 Улучш. Стервятник"
  },
  Event_118430_ChoiceDesc2 = {
    Text = "[Заглянуть в будущее]получено Золотая реликвия \"(RelicConfig.Arg1)\", Погружение \"(Skill.Arg2)\""
  },
  Event_118430_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_118430_Desc = {
    Text = "Ничто в мире не может оставаться неизменным.\nДаже рай, созданный Богиней-Матерью, не исключение.\nВ краткий миг ты увидел нечто сквозь пространственно-временной разлом.\nПрошлое, настоящее, будущее переплетаются в этой испещрённой трещинами расщелине, непрестанно меняясь.\nОжидая твоего любопытного взгляда."
  },
  Event_118430_Name = {
    Text = "Пространственно-временной разлом"
  },
  Event_118431_ChoiceDesc1 = {
    Text = "\"Получить 100 чёрных печатей\""
  },
  Event_118431_ChoiceDesc2 = {
    Text = "[2 случайные Командные карты получают Гриф: «(EnchantConfig.Arg1)»]"
  },
  Event_118431_Desc = {
    Text = "Незримая воля не принимает твой выбор. Она готова дать тебе ещё один шанс измениться —\nБудь осторожен: даже бесплотная музыка способна забирать жизни."
  },
  Event_118431_Name = {
    Text = "«Совершенный» гимн"
  },
  Event_118432_ChoiceDesc1 = {
    Text = "[Покормить крыс]получить серебряное создание «(RelicConfig.Arg1)», выбрать 1 симптом заражения"
  },
  Event_118432_ChoiceDesc2 = {
    Text = "[Прогнать крыс]выберите 1 карту команды из 3 и получите гравировку: «(EnchantConfig.Arg1)», инфицируйтесь «(Skill.Arg2)»"
  },
  Event_118432_ChoiceDesc3 = {
    Text = "[Игнорировать крыс] получить 25 чёрных печатей"
  },
  Event_118432_Desc = {
    Text = "Всё на этом корабле пребывает в круговороте перерождений.\nТе мерзкие, покрытые грязным пухом маленькие создания, что промышляют на борту, тоже не могут избежать этой участи.\nРаз за разом, цикл за циклом, они пожирают всё, что видят, но так и не могут насытиться.\n«Так… голодно…»\nСтаи крыс издают болезненный пронзительный визг.\nБесконечные перерождения довели их до невыносимого голода — они должны что-нибудь съесть.\nНемедленно, сейчас же!"
  },
  Event_118432_Name = {
    Text = "Голодная стая крыс"
  },
  Event_118433_ChoiceDesc1 = {
    Text = "[Отвести взгляд]получить Золотая реликвия «(RelicConfig.Arg1)», Погружение «(Skill.Arg2)»"
  },
  Event_118433_ChoiceDesc2 = {
    Text = "[Взглянуть в глаза]случайно пробуждает 2 пробуждающих тела, инфицирует дважды «(Skill.Arg1)»"
  },
  Event_118433_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_118433_Desc = {
    Text = "Как и звёзды на небе, в глубинах моря тоже, конечно, множество глаз.\nЭти глаза принадлежат рыбам, обитающим на дне, кощунственным жаберным созданиям, а также самому океану.\nТише, не тревожь их.\nНе тревожь безумие глубин."
  },
  Event_118433_Name = {
    Text = "Глаза глубин"
  },
  Event_118434_ChoiceDesc1 = {
    Text = "[Игнорировать шёпот]"
  },
  Event_118434_ChoiceDesc2 = {
    Text = "[Внимать шёпоту]"
  },
  Event_118434_ChoiceDesc3 = {
    Text = "[Контрпропаганда]"
  },
  Event_118434_Desc = {
    Text = "«Жаждешь обрести благосклонность божества? Хочешь познать смысл своего существования?»\nВздох раздался у тебя в ушах — словно бормотание безумца самому себе, словно интимный шёпот незримого существа.\nРазум и бдительность заставили тебя отказать, но голос продолжал говорить сам с собой.\n«Прояви Выдержка и выслушай. То, что тебе предстоит узнать, — истина о судьбе мира…»"
  },
  Event_118434_Name = {
    Text = "Проповедь Незримого"
  },
  Event_118435_ChoiceDesc1 = {
    Text = "[Восприятие мозга]Выберите 1 Карту команды из 3 для получения гравировки: \"(EnchantConfig.Arg1)\""
  },
  Event_118435_ChoiceDesc2 = {
    Text = "[Восприятие души]Инфицирует \"(Skill.Arg1)\", ещё одна случайная гравировка"
  },
  Event_118435_Desc = {
    Text = "Мозг, надёжно защищённый внутри черепа, передал тебе некую информацию.\nТы не знаешь, не была ли она искажена при преобразовании нейромедиаторов и передаче биоэлектрических импульсов.\nЕдинственный неоспоримый факт — ты принял эту информацию и в объективном существовании своего тела ощутил собственную жизнь."
  },
  Event_118435_Name = {
    Text = "Клетка разума"
  },
  Event_118436_ChoiceDesc1 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_118436_Desc = {
    Text = "«Неплохой Лечение, но, к сожалению, не правильный.»\n«А какой тогда правильный?»\nНеведомое существо не ответило на твой вопрос, лишь презрительно усмехнулось.\n«Кто тебе сказал, что у судьбы есть правильный Лечение?»"
  },
  Event_118436_Name = {
    Text = "Авантюра судьбы"
  },
  Event_118437_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118437_Desc = {
    Text = "«Ты думаешь, я не пытался перерезать их? Нет, когда ты сопротивляешься желаниям, они лишь становятся сильнее!»\nЧувствуя, как верёвки, сотканные из желаний, стягиваются всё туже, врезаясь в плоть, голос издаёт отчаянный крик.\n«Я никогда не избавлюсь от них… никогда!»"
  },
  Event_118437_Name = {
    Text = "Оковы желания"
  },
  Event_118438_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 25 чёрных печатей, заразиться «(Skill.Arg2)», продолжить выбор"
  },
  Event_118438_ChoiceDesc2 = {
    Text = "[Пустить на самотёк] покинуть"
  },
  Event_118438_Desc = {
    Text = "Чёрная ворона плачет.\nЧёрная ворона кричит.\nЧёрная ворона воет.\nНо для людей она просто поёт.\n«Ах, какое беззаботное пение. Как бы я хотел тоже быть вороной, вдали от мирских забот.»"
  },
  Event_118438_Name = {
    Text = "Неощутимый плач"
  },
  Event_118439_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118439_Desc = {
    Text = "Бабочки рассеялись, и ты наконец разглядел печатную машинку внизу.\nЭто бедное создание, уже лишённое жизни, последним усилием напечатало два слова: «Уйти»."
  },
  Event_118439_Name = {
    Text = "Душа порхает, как Глава о бабочке"
  },
  Event_118440_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118440_Desc = {
    Text = "В образах прошлого девушка в пушистой шубе машет тебе рукой.\nТы не можешь разобрать, что она говорит, но видишь улыбку на её лице."
  },
  Event_118440_Name = {
    Text = "Пространственно-временной разлом"
  },
  Event_118441_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118441_Desc = {
    Text = "Глубины вновь погрузились в непроглядную тьму и тишину.\nВ этой тьме и тишине ты снова услышал биение сердца.\nЭтот звук шёл изнутри тебя.\nВ глазах других ты тоже лишь бьющееся сердце, плывущее в непроглядной бездне."
  },
  Event_118441_Name = {
    Text = "Закон джунглей"
  },
  Event_118442_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118442_Desc = {
    Text = "На этот раз в Пепел обратились не те, кто стоял на пути, а ступающие по морю.\nЗвёзды безмолвно взирали на эту сцену, храня молчание, как и на протяжении прошедших тысячелетий."
  },
  Event_118442_Name = {
    Text = "Ожидание под звёздами"
  },
  Event_118443_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118443_Desc = {
    Text = "Несмотря на численное превосходство, трусость этих грязных грызунов оказалась ещё больше их самих.\nНапуганные твоим решительным настроем, они разбежались врассыпную."
  },
  Event_118443_Name = {
    Text = "Голодная стая крыс"
  },
  Event_118444_ChoiceDesc1 = {
    Text = "[Протянуть руку помощи]Случайное пробуждение одного пробуждающего тела, Погружение \"(Skill.Arg1)\""
  },
  Event_118444_ChoiceDesc2 = {
    Text = "[Молча наблюдать] Выбрать одну из трёх гравировок"
  },
  Event_118444_Desc = {
    Text = "Бьющееся сердце плывёт в кромешной тьме глубин.\nВозможно, оно принадлежит рыбе, а возможно — некоему существу с жабрами.\nТы не можешь разглядеть. Единственное, что ты видишь отчётливо — это непрестанно бьющееся сердце и разверзающуюся за ним кровавую пасть.\nОхотиться или быть добычей — таков закон природы.\nБудь то на суше или в океане."
  },
  Event_118444_Name = {
    Text = "Закон джунглей"
  },
  Event_118445_ChoiceDesc1 = {
    Text = "[Отмахнуться] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)», заражение «(Skill.Arg2)»"
  },
  Event_118445_ChoiceDesc2 = {
    Text = "\"Разрешить пребывание\" получить Серебряная реликвия \"(RelicConfig.Arg1)\", инфицирование \"(Skill.Arg2)\""
  },
  Event_118445_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_118445_Desc = {
    Text = "Из темноты донёсся тихий звук.\nЭто Глава о бабочке вежливо спрашивала.\n«Можно мне опуститься на твою ладонь?»\n«Я просто очень устала и хочу немного отдохнуть...»\nТак спрашивая, Глава о бабочке пролетела сквозь тьму и закружилась перед тобой.\nЧёрная слизь капала с её крыльев — дар тьмы, полученный бабочкой при пересечении мрака."
  },
  Event_118445_Name = {
    Text = "Просьба бабочки"
  },
  Event_118446_ChoiceDesc1 = {
    Text = "\"Покинуть\" получить Золотая реликвия \"(RelicConfig.Arg1)\""
  },
  Event_118446_Desc = {
    Text = "После минуты молчания что-то было брошено тебе в руки.\n«Бери и уходи.»\n«Судьба всегда щедра к везунчикам.»"
  },
  Event_118446_Name = {
    Text = "Авантюра судьбы"
  },
  Event_118447_ChoiceDesc1 = {
    Text = "[Следовать указанию] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)», заразить «(Skill.Arg2)»"
  },
  Event_118447_ChoiceDesc2 = {
    Text = "[Игнорировать указание] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)», заразить «(Skill.Arg2)»"
  },
  Event_118447_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_118447_Desc = {
    Text = "Празднество уже началось.\nПод пламенем духов и молитвами крови бесчисленные души верующих обратились в маяки —\nПризрачные духи рассеялись вокруг тебя, словно путеводные феи, мерцая светом в ожидании твоего выбора."
  },
  Event_118447_Name = {
    Text = "Маяк душ"
  },
  Event_118448_ChoiceDesc1 = {
    Text = "\"покинуть\" инфицировано \"(Skill.Arg1)\", получить 50 чёрных печатей"
  },
  Event_118448_Desc = {
    Text = "«Невежественный человек!»\nГолос издал досадливую жалобу, но не дошёл до гнева.\nИбо он знал: у невежд всегда наступает миг просветления.\nЕму лишь нужно дождаться этого дня.\nА до его наступления — выжечь на тебе клеймо божества, утвердив принадлежность твоей души."
  },
  Event_118448_Name = {
    Text = "Проповедь Незримого"
  },
  Event_118449_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118449_Desc = {
    Text = "«@2 — @3…»\nОгромный поток знаний хлынул в твой мозг вместе с кощунственной мелодией.\nНо человеческое тело ограничивает тебя, не позволяя постичь знания, пришедшие из вселенной.\nКакое жалкое сожаление."
  },
  Event_118449_Name = {
    Text = "Кощунственная мелодия"
  },
  Event_118450_ChoiceDesc1 = {
    Text = "\"покинуть\" инфицировано \"(Skill.Arg1)\", получить 50 чёрных печатей"
  },
  Event_118450_Desc = {
    Text = "«Вообще-то, у меня тоже есть одна истина о мире, которую я хотел бы тебе поведать…»\n«Мир был создан Летающим Макаронным Монстром, у которого два глаза из мудрых фрикаделек и макаронные щупальца, символизирующие бесконечную силу…»\nТы серьёзно нёс эту забавную чушь, ожидая реакции собеседника.\nНо прошло много времени, а с той стороны — ни звука.\n«Эх, похоже, фанатики не понимают юмора.»\nТы вздохнул и ушёл."
  },
  Event_118450_Name = {
    Text = "Проповедь Незримого"
  },
  Event_118451_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118451_Desc = {
    Text = "Твоя настройка не привела эти хаотичные ноты к гармонии.\nНо по крайней мере незримая воля увидела твою попытку.\nЭто хорошее Начало."
  },
  Event_118451_Name = {
    Text = "«Совершенный» гимн"
  },
  Event_118452_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118452_Desc = {
    Text = "Три силуэта дрожат, беззвучно всхлипывая.\nИх Твёрдая Твёрдая вера была поставлена тобой под сомнение, а это — оскорбление, которое фанатики не могут стерпеть."
  },
  Event_118452_Name = {
    Text = "Лучшее подношение"
  },
  Event_118453_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118453_Desc = {
    Text = "В образах будущего девушка с отросшими щупальцами надменно бросила на тебя взгляд и резко прикрикнула.\n«Истинный облик Божественной Матери не терпит осквернения.»\nИ тогда образ исчез, а пространственно-временная трещина мгновенно закрылась. Оставив тебя наедине с воспоминаниями об увиденном."
  },
  Event_118453_Name = {
    Text = "Пространственно-временной разлом"
  },
  Event_118454_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118454_Desc = {
    Text = "Тебе удалось оторваться от ступающих по морю и продолжить стремительный путь вперёд.\nНад твоей головой звёзды тихо сияли, как и на протяжении прошедших тысячелетий."
  },
  Event_118454_Name = {
    Text = "Ожидание под звёздами"
  },
  Event_118455_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118455_Desc = {
    Text = "Непостижимое существо не стало тебя удерживать.\n«Однажды ты вернёшься.»\n«Никто не может отвергнуть судьбу.»"
  },
  Event_118455_Name = {
    Text = "Авантюра судьбы"
  },
  Event_118456_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118456_Desc = {
    Text = "Одним чётким движением руки бессильно повисли.\nНо ты не пропустил последний вздох.\nОн наконец-то по-настоящему освободился от своих бесконечных желаний."
  },
  Event_118456_Name = {
    Text = "Оковы желания"
  },
  Event_118457_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118457_Desc = {
    Text = "Быть неощутимым — неизбежная Колесо Судьбы этого мира.\nНикто не способен полностью разделить чувства другого существа."
  },
  Event_118457_Name = {
    Text = "Неощутимый плач"
  },
  Event_118458_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 35 чёрных печатей, заразиться «(Skill.Arg2)», продолжить выбор"
  },
  Event_118458_ChoiceDesc2 = {
    Text = "[Пустить на самотёк] покинуть"
  },
  Event_118458_Desc = {
    Text = "Чёрная ворона плачет.\nЧёрная ворона кричит.\nЧёрная ворона воет.\nНо для людей она просто поёт.\n«Ах, какое беззаботное пение. Как бы я хотел тоже быть вороной, вдали от мирских забот.»"
  },
  Event_118458_Name = {
    Text = "Неощутимый плач"
  },
  Event_118459_ChoiceDesc1 = {
    Text = "\"Слушай внимательно\"получить серебряное создание \"(RelicConfig.Arg1)\", заражено \"(Skill.Arg2)\""
  },
  Event_118459_ChoiceDesc2 = {
    Text = "\"Закрыть уши\" получить гравировку из 3 вариантов"
  },
  Event_118459_Desc = {
    Text = "В незримом безумии тебе почудилось фортепиано.\nНевидимые руки неразличимых очертаний порхали по незримым клавишам, исполняя кощунственную мелодию.\nЗловещая музыка зазвучала из глубин твоей души, по проводам кровеносных сосудов достигая трепещущего мозга."
  },
  Event_118459_Name = {
    Text = "Кощунственная мелодия"
  },
  Event_118460_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118460_Desc = {
    Text = "Вдохновения, наваждения и безумные фантазии смешались воедино, сливаясь в самый яркий цвет на свете.\nТы видишь, как пространство складывается внутри тебя, а время кружится по твоей воле.\nВ этот миг ты постиг пространство и время — всемогущий, всеведущий.\nРазумеется, за это пришлось заплатить свою цену."
  },
  Event_118460_Name = {
    Text = "Калейдоскоп разума"
  },
  Event_118461_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118461_Desc = {
    Text = "Хаотичные души пронзительным воем указывают тебе путь.\nБезопасен ли этот путь? Ты не знаешь.\nТвой единственный выбор — продолжать идти вперёд."
  },
  Event_118461_Name = {
    Text = "Маяк душ"
  },
  Event_118462_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 40 чёрных печатей, заразиться «(Skill.Arg2)», продолжить выбор"
  },
  Event_118462_ChoiceDesc2 = {
    Text = "\"Оставить как есть\" получить 25 чёрных печатей и покинуть"
  },
  Event_118462_Desc = {
    Text = "Чёрная ворона плачет.\nЧёрная ворона кричит.\nЧёрная ворона воет.\nНо для людей она просто поёт.\n«Ах, какое беззаботное пение. Как бы я хотел тоже быть вороной, вдали от мирских забот.»"
  },
  Event_118462_Name = {
    Text = "Неощутимый плач"
  },
  Event_118463_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118463_Desc = {
    Text = "Хаотичная душа издала скорбный вздох.\nОна постепенно рассеялась, но тот скорбный вздох, словно обретя плоть, опустился на твоё сердце.\nТук-тук — твоё сердцебиение зазвучало в унисон с музыкой ритуала."
  },
  Event_118463_Name = {
    Text = "Маяк душ"
  },
  Event_118464_ChoiceDesc1 = {
    Text = "\"Покинуть\" получить серебряное создание \"(RelicConfig.Arg1)\""
  },
  Event_118464_Desc = {
    Text = "«О, о, какой же это набожный агнец!»\nГолос восклицал с восторженным восхвалением.\n«Когда наш Владыка пробудится, такой агнец, как ты, непременно обретёт пристанище в том возвышенном и великом Царстве Божьем…»"
  },
  Event_118464_Name = {
    Text = "Проповедь Незримого"
  },
  Event_118465_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118465_Desc = {
    Text = "«Небо» снисходительно к твоему упрямству.\nОднажды заблудшее дитя вернётся в объятия матери.\nВедь тебе некуда бежать."
  },
  Event_118465_Name = {
    Text = "Объятия океана"
  },
  Event_118466_ChoiceDesc1 = {
    Text = "[принять объятия]получить серебряное создание «(RelicConfig.Arg1)», Погружение «(Skill.Arg2)»"
  },
  Event_118466_ChoiceDesc2 = {
    Text = "[отвергнуть объятия]получить серебряное создание «(RelicConfig.Arg1)», Погружение «(Skill.Arg2)»"
  },
  Event_118466_ChoiceDesc3 = {
    Text = "[выплыть на поверхность] получить 25 чёрных печатей"
  },
  Event_118466_Desc = {
    Text = "Мир опрокидывается в твоих глазах.\nВ этот миг окружающая тебя глубина — это «небо».\nВ агонии, близкой к утоплению, эта тёмно-синяя «небесная гладь» нежно приближается, намереваясь заключить тебя в объятия.\nОна не судит, лишь дарует."
  },
  Event_118466_Name = {
    Text = "Объятия океана"
  },
  Event_118467_ChoiceDesc1 = {
    Text = "[Прикрикнуть на них]получить проклятое творение «(RelicConfig.Arg1)» и заразиться «(Skill.Arg2)»"
  },
  Event_118467_ChoiceDesc2 = {
    Text = "[Откликнуться на них] Выбрать 1 из 3 Командных карт и получить Гриф: [(EnchantConfig.Arg1)]"
  },
  Event_118467_ChoiceDesc3 = {
    Text = "[Проигнорировать их] получить 50 чёрных печатей"
  },
  Event_118467_Desc = {
    Text = "Три размытые души преградили тебе путь.\nОдна фигура благоговейно поклонилась тебе, умоляя даровать кровь. Твоя текущая кровь — лучшее подношение богу.\nДругая фигура холодно занесла над тобой нож, намереваясь отсечь твою плоть. Немутировавшая человеческая плоть непременно завоюет благосклонность бога.\nПоследняя лишь безмолвно смотрела на тебя, надеясь, что ты заберёшь её жизнь, доказав тем самым искреннейшую веру."
  },
  Event_118467_Name = {
    Text = "Лучшее подношение"
  },
  Event_118468_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 30 чёрных печатей, заразиться «(Skill.Arg2)», продолжить выбор"
  },
  Event_118468_ChoiceDesc2 = {
    Text = "[Пустить на самотёк] покинуть"
  },
  Event_118468_Desc = {
    Text = "Чёрная ворона плачет.\nЧёрная ворона кричит.\nЧёрная ворона воет.\nНо для людей она просто поёт.\n«Ах, какое беззаботное пение. Как бы я хотел тоже быть вороной, вдали от мирских забот.»"
  },
  Event_118468_Name = {
    Text = "Неощутимый плач"
  },
  Event_118469_ChoiceDesc1 = {
    Text = "\"покинуть\" заражает \"(Skill.Arg1)\""
  },
  Event_118469_ChoiceDesc2 = {
    Text = "\"покинуть\" заражает \"(Skill.Arg1)\""
  },
  Event_118469_ChoiceDesc3 = {
    Text = "\"покинуть\" заражает \"(Skill.Arg1)\""
  },
  Event_118469_Desc = {
    Text = "«Нет! Нам это не нужно! Нам нужно что-то более… вкусное.»\n«А именно… твою плоть и кровь!»\nСтая крыс издала пронзительный визг и хлынула к тебе.\nПохоже, чрезмерная доброта иногда только навлекает беду."
  },
  Event_118469_Name = {
    Text = "Голодная стая крыс"
  },
  Event_118470_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118470_Desc = {
    Text = "Твоё уважение снискало расположение этих глаз.\nПеред исчезновением они сквозь бурлящую воду преподнесли тебе Подарок.\nЭто свидетельство того, что глубины укротили тебя."
  },
  Event_118470_Name = {
    Text = "Глаза глубин"
  },
  Event_118471_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118471_Desc = {
    Text = "Под твоим неприкрытым взглядом глубины медленно пробуждаются.\nМорская вода неистово бурлит вокруг тебя, принося неизъяснимый Бред.\nПочувствуй Негодование глубин — это и благословение, и проклятие."
  },
  Event_118471_Name = {
    Text = "Глаза глубин"
  },
  Event_118472_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 20 чёрных печатей и заразить «(Skill.Arg2)»"
  },
  Event_118472_ChoiceDesc2 = {
    Text = "[Пустить на самотёк] покинуть"
  },
  Event_118472_Desc = {
    Text = "Чёрная ворона плачет.\nЧёрная ворона кричит.\nЧёрная ворона воет.\nНо для людей она просто поёт.\n«Ах, какое беззаботное пение. Как бы я хотел тоже быть вороной, вдали от мирских забот.»"
  },
  Event_118472_Name = {
    Text = "Неощутимый плач"
  },
  Event_118473_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118473_Desc = {
    Text = "Кровь, куски плоти, жизнь.\nПодношение готово, теперь остаётся лишь тихо ждать пиршества бога."
  },
  Event_118473_Name = {
    Text = "Лучшее подношение"
  },
  Event_118474_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118474_Desc = {
    Text = "Бабочка поняла твой отказ.\nКрылья, покрытые чёрной слизью, снова затрепетали, и она закачалась в темноте, порхая из стороны в сторону.\nВскоре тьма вновь поглотила бабочку. На этот раз у неё не осталось сил сопротивляться."
  },
  Event_118474_Name = {
    Text = "Просьба бабочки"
  },
  Event_118475_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118475_Desc = {
    Text = "Бабочка опустилась на твою ладонь, а вместе с ней — чёрная слизь с её пёстрых крыльев.\nПод твои вздохи пёстрые крылья постепенно растаяли, слившись с чёрной слизью в неведомую хаотичную форму.\nЭтой бабочке больше не придётся проходить сквозь тьму.\nОна уснула вечным сном на твоей ладони."
  },
  Event_118475_Name = {
    Text = "Просьба бабочки"
  },
  Event_118477_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118477_Desc = {
    Text = "Охрипшая ворона наконец закрыла глаза.\nВ неведомой никому, неощутимой ненависти она испустила последний вздох и превратилась в лужу чёрной густой жидкости."
  },
  Event_118477_Name = {
    Text = "Неощутимый плач"
  },
  Event_118478_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118478_Desc = {
    Text = "«Спасибо тебе...»\nБьющееся сердце радостно устремилось вдаль.\nВскоре из непроглядных глубин донёсся звук пережёвывания плоти."
  },
  Event_118478_Name = {
    Text = "Закон джунглей"
  },
  Event_118479_ChoiceDesc1 = {
    Text = "[Принять Приглашение]заражает «(Skill.Arg1)», получение проклятого создания – «(RelicConfig.Arg2)»"
  },
  Event_118479_ChoiceDesc2 = {
    Text = "[Отклонить Приглашение] Выбрать 1 создание для уничтожения и получить 1 награду"
  },
  Event_118479_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_118479_Desc = {
    Text = "«Всё на этом корабле должно стать частью этого бесконечно рушащегося и перезапускающегося циклического рая.»\nБезумные мелодии зазвучали в твоём сознании — это незримая воля просвещает тебя.\n«Здесь нет плача, нет печали, лишь чистая священная музыка и вечный смех.»\n«Желаешь ли ты присоединиться к раю и стать частью этой совершенной мелодии?»"
  },
  Event_118479_Name = {
    Text = "«Совершенный» гимн"
  },
  Event_118480_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_118480_Desc = {
    Text = "В твоём молчании души беззвучно рассеиваются.\nТе, кто не понимает веры, не стоят того, чтобы тратить на них время."
  },
  Event_118480_Name = {
    Text = "Лучшее подношение"
  },
  Event_123616_ChoiceDesc1 = {
    Text = "[Получить стандартное творение]"
  },
  Event_123616_Desc = {
    Text = "Установите безумие всех Пробуждённых на 100, Cеребряный ключ на 1000, здоровье на 80%.\nУдалите 2 карты, добавьте 3 симптом карты.\nУстановите Багровое горнило на 12.5%, выберите 4 карты для помещения в Ультра пространство.\nПолучите стандартный пакет реликвий."
  },
  Event_123616_Name = {
    Text = "Одним нажатием пропустить путь"
  },
  Event_125696_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125696_Desc = {
    Text = "Беспричинный Негодование овладевает тобой, ты поднимаешь руку и яростно отгоняешь их. Ты слишком долго блуждал среди загадок — быть может, ты жаждешь упоительной битвы или даже просто конца…\nНо вороны ничего не сделали. Под твоим взглядом бездна рассеялась.\nСтая воронов исчезла на краю сцены — там, куда тебе предстоит отправиться."
  },
  Event_125696_Name = {
    Text = "Бездна воронов"
  },
  Event_125697_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125697_Desc = {
    Text = "«Трусишка.» Женский голос не скрывал насмешки в своём смехе.\n«Уходи. Чем дальше, тем лучше.»"
  },
  Event_125697_Name = {
    Text = "Замок судьбы"
  },
  Event_125698_ChoiceDesc1 = {
    Text = "[Прогнать] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)», заражение «(Skill.Arg2)»"
  },
  Event_125698_ChoiceDesc2 = {
    Text = "[Выслушать]Получить серебряный артефакт «(RelicConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125698_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_125698_Desc = {
    Text = "В темноте раздался тихий звук. Бабочка приземлилась на твою ладонь. Ты помнишь её. \n«Мисс Арахна... ты никогда нас не покидала, верно?» \nКрасивый узор бабочки, смотрящий на человека рядом с тобой."
  },
  Event_125698_Name = {
    Text = "Остаток жизни бабочки"
  },
  Event_125699_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125699_Desc = {
    Text = "Звуки и слова, подобно пчелиному рою, вторгаются в твой разум. Ты затаив дыхание изгоняешь ненужные мысли из головы.\nИгнорировать куда труднее, чем читать, но тебе это удалось."
  },
  Event_125699_Name = {
    Text = "Межпространственная телеграмма"
  },
  Event_125700_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125700_Desc = {
    Text = "Это Иллюзия, созданная врагом!\nВы качаете головой, приходите в себя и снова крепко сжимаете Cеребряный ключ в руке."
  },
  Event_125700_Name = {
    Text = "Отражение в вине"
  },
  Event_125701_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125701_Desc = {
    Text = "Вы пристально вглядываетесь в этот глаз, стараясь увидеть и услышать. Вы пытаетесь проникнуть в душу актёра, прочувствовать его страдания.\nВы приближаетесь, приближаетесь. Вы проходите сквозь его тело и касаетесь его души…\nВы резко открываете глаза и обнаруживаете, что стоите в центре сцены, а слёзы стекают по кончикам пальцев.\nЭто была ваша исповедь перед зрителями."
  },
  Event_125701_Name = {
    Text = "Исповедь актёра"
  },
  Event_125702_ChoiceDesc1 = {
    Text = "[Обсудить с ней] Удалить 1 командную карту, получить Arg1 тёмных печатей"
  },
  Event_125702_ChoiceDesc2 = {
    Text = "[Промолчать]"
  },
  Event_125702_Desc = {
    Text = "«Счастливый финал, конечно, прекрасен, но фальшивое счастье никогда не сможет коснуться сердец зрителей…»\nДраматург закрывает глаза в раздумьях. Этот финал её не устраивает."
  },
  Event_125702_Name = {
    Text = "Финал пьесы"
  },
  Event_125703_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 35 чёрных печатей, заразиться «(Skill.Arg2)», продолжить выбор"
  },
  Event_125703_ChoiceDesc2 = {
    Text = "[Пустить на самотёк] покинуть"
  },
  Event_125703_Desc = {
    Text = "«Скрип— скрип— богиня судьбы вращает свою прялку.\nСкрип— скрип— нити судьбы сплетаются в её руках.»"
  },
  Event_125703_Name = {
    Text = "Последнее Пророчество"
  },
  Event_125704_ChoiceDesc1 = {
    Text = "[Вы сами] Случайно получить 3 командные карты из колоды и выбрать 1 для копирования"
  },
  Event_125704_ChoiceDesc2 = {
    Text = "[Уильям] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125704_ChoiceDesc3 = {
    Text = "[Никто] Получить 25 чёрных печатей"
  },
  Event_125704_Desc = {
    Text = "Вы уверены, что не пьяны, но, взглянув в Прекрасное Прекрасное вино, вы погрузились в тихое озеро.\nВ изящном бокале отражается силуэт — кто это?"
  },
  Event_125704_Name = {
    Text = "Отражение в вине"
  },
  Event_125705_ChoiceDesc1 = {
    Text = "[Слушать]Получить Серебряная реликвия «(RelicConfig.Arg1)»"
  },
  Event_125705_ChoiceDesc2 = {
    Text = "[Прогнать]Получить 75 тёмных печатей, Погружение «(Skill.Arg2)»"
  },
  Event_125705_Desc = {
    Text = "Когда ты приближаешься к силе Эона внутри себя, в твоём сознании появляется стая воронов, кружащая в твоём смятённом Духовном пространстве.\n\nВороны окружают тебя, и перевёрнутая бездна вращается над твоей головой.\nСто тысяч воронов кричат в унисон — как насмешливое пророчество."
  },
  Event_125705_Name = {
    Text = "Бездна воронов"
  },
  Event_125706_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125706_Desc = {
    Text = "Ты и Арахна пытаетесь стабилизировать разрушенную судьбу рядом с вами. Ваши усилия приносят немного результатов, но этого уже достаточно. Используя время, которое вы смогли выиграть, вы продолжаете приближаться к Нефрее. \n Ты пришел сюда, чтобы принести ей освобождение."
  },
  Event_125706_Name = {
    Text = "Финал Паутины судьбы"
  },
  Event_125707_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 20 чёрных печатей и заразить «(Skill.Arg2)»"
  },
  Event_125707_ChoiceDesc2 = {
    Text = "[Пустить на самотёк] покинуть"
  },
  Event_125707_Desc = {
    Text = "«Они умирают вместе с сетью, беззвучно.»"
  },
  Event_125707_Name = {
    Text = "Последнее Пророчество"
  },
  Event_125708_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125708_Desc = {
    Text = "Это телеграмма, адресованная Бездне.\n«Не торопитесь, дети мои. Ворота темницы вот-вот откроются, и ваша свобода близка.»"
  },
  Event_125708_Name = {
    Text = "Межпространственная телеграмма"
  },
  Event_125709_ChoiceDesc1 = {
    Text = "[Прогнать] 1 случайная Командная карта получает Гриф: «(EnchantConfig.Arg1)», заразить «(Skill.Arg2)»"
  },
  Event_125709_ChoiceDesc2 = {
    Text = "[Выслушать]Выбрать 1 из 3 командных карт для получения гравировки: «(EnchantConfig.Arg1)»"
  },
  Event_125709_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_125709_Desc = {
    Text = "Бабочка легко опускается на твою ладонь. Прекрасные узоры на её крыльях, словно глаза, тихо смотрят на тебя.\nБыть может, она хочет тебе что-то сказать?"
  },
  Event_125709_Name = {
    Text = "Привал бабочки"
  },
  Event_125710_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125710_Desc = {
    Text = "Двадцать пар скорбных глаз смотрят на тебя. Ворон прекращает петь и с последним пророчеством покидает эту шаткую, готовую рухнуть сеть."
  },
  Event_125710_Name = {
    Text = "Последнее Пророчество"
  },
  Event_125711_ChoiceDesc1 = {
    Text = "\"наклониться и выглянуть\"заразились\"(Skill.Arg1)\", получили Золотая реликвия\"(RelicConfig.Arg2)\""
  },
  Event_125711_ChoiceDesc2 = {
    Text = "\"Отказаться от Просмотреть\"получить 50 чёрные Печать пакиа"
  },
  Event_125711_Desc = {
    Text = "Завернув за угол, ты замечаешь скромный кинозал. Ты не помнишь, чтобы в Лондиниуме было такое заведение."
  },
  Event_125711_Name = {
    Text = "Кинозал воспоминаний"
  },
  Event_125712_ChoiceDesc1 = {
    Text = "[Принять судьбу]Выберите 1 из 3 командных карт, чтобы получить Очарование: «(EnchantConfig.Arg1)»"
  },
  Event_125712_ChoiceDesc2 = {
    Text = "[Противостоять судьбе]Заразиться «(Skill.Arg1)», перегравировать, можно выполнить до 2 раз"
  },
  Event_125712_Desc = {
    Text = "«Ах, мы снова встретились, дорогой.»\nТы начинаешь наслаждаться молодым женским голосом, звучащим в твоём разуме. Он нежен, соблазнителен, словно паутина, ловящая мошек.\n«Ну же, скажи мне, ты готов принять свою судьбу?»"
  },
  Event_125712_Name = {
    Text = "Клетка судьбы"
  },
  Event_125713_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125713_Desc = {
    Text = "«Глупый человек, мы что, близко знакомы?»\nЧёрная кошка презрительно покосилась на тебя и отвернулась.\n«Уходи отсюда. И больше не делай подобных глупостей.»"
  },
  Event_125713_Name = {
    Text = "Иллюзорное превращение"
  },
  Event_125714_ChoiceDesc1 = {
    Text = "[Сделать фото]Выберите 1 из 3 командных карт, чтобы получить Очарование: «(EnchantConfig.Arg1)»"
  },
  Event_125714_ChoiceDesc2 = {
    Text = "[Сменить позу]Заражение «(Skill.Arg1)», сменить Очарование из варианта 1, можно использовать дважды"
  },
  Event_125714_Desc = {
    Text = "Камера одиноко стоит на сцене, её чёрный объектив смотрит на тебя, словно загадочный фасеточный глаз, созданный механическим божеством.\n«В этом театре давно не было зрителей… Добро пожаловать! Добро пожаловать! Давайте сделаем фото! Совершенно бесплатно!»\nКамера возбуждённо кричит. На этой сцене, которая никому не нужна, она — единственная звезда."
  },
  Event_125714_Name = {
    Text = "Снимок из зрительного зала"
  },
  Event_125715_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125715_Desc = {
    Text = "«Как может тот, кто не задаёт вопросов судьбе, надеяться на её Лечение?»"
  },
  Event_125715_Name = {
    Text = "Замок судьбы"
  },
  Event_125716_ChoiceDesc1 = {
    Text = "[Обдумать Выход]Получить серебряную Реликвию «(RelicConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125716_ChoiceDesc2 = {
    Text = "[Плыть по течению]Получить золотую Реликвию «(RelicConfig.Arg1)», заразиться «(Skill.Arg2)», «(Skill.Arg3)»"
  },
  Event_125716_ChoiceDesc3 = {
    Text = "\"Всплытие\" получить 25 чёрных печатей"
  },
  Event_125716_Desc = {
    Text = "Новая сцена, две пересекающиеся жизни... На пути к укрытию от полиции тыприводя в порядок то, что рассказала тебе Арахна. \n В бурных мыслях ты погружаешься в спокойное Эквор."
  },
  Event_125716_Name = {
    Text = "Тишина"
  },
  Event_125717_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125717_Desc = {
    Text = "Бабочка перелетает на твоё плечо и приближается к уху. Ты внимательно слушаешь, но слышишь лишь трепет её крыльев, подобный беззвучному вздоху.\nПока ты слушаешь, пёстрые крылья постепенно тают, и Глава о бабочке засыпает вечным сном на твоём плече.\nТы уже никогда не узнаешь, что она хотела тебе сказать."
  },
  Event_125717_Name = {
    Text = "Остаток жизни бабочки"
  },
  Event_125718_ChoiceDesc1 = {
    Text = "[Откусить]Случайно пробудить 1 пробуждённого, заразиться «(Skill.Arg1)»"
  },
  Event_125718_ChoiceDesc2 = {
    Text = "[Отказаться] получает 3 на выбор Текст молитвы"
  },
  Event_125718_Desc = {
    Text = "«Проголодался, дорогой Гость?»\nЛипкий голос раздаётся из-за барной стойки. Ты оборачиваешься, но не видишь никого.\n«Закуски бара «Полуночная маска» тоже славятся повсюду. Не хочешь попробовать?»"
  },
  Event_125718_Name = {
    Text = "Вкус судьбы"
  },
  Event_125719_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125719_Desc = {
    Text = "Ты не осмеливаешься читать написанное выше, а только внимательно рассматриваешь тот изящный конверт. \n На конверте восковая печать с размытым родовым гербом, на котором красивым каллиграфическим шрифтом написано: \n «К госпоже Арахне, новорождённой.» \n «Ваш преданный Сквайр, Эдгар.»"
  },
  Event_125719_Name = {
    Text = "Спокойной ночи, мистер Эдгар"
  },
  Event_125720_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125720_Desc = {
    Text = "«Вот как… Я поняла, сестра…»\n«Драматург никогда не мог переписать судьбу персонажа. Та горестная участь была предрешена с самого начала, и даже ты никогда не могла её изменить…»\nПечальные всхлипы стихли. Печатная машинка драматурга обратилась в бабочек, рассеявшихся по пустому Театру Судьбы, и исчезла без следа."
  },
  Event_125720_Name = {
    Text = "Финал пьесы"
  },
  Event_125721_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125721_Desc = {
    Text = "Неизвестные актёры, опасные па… Какая разница? Ничего хуже самой судьбы быть не может.\nВы протягиваете руку и ступаете на сцену. Марионетки берут вас за руки и пускаются в весёлый танец.\nВы слышите аплодисменты."
  },
  Event_125721_Name = {
    Text = "Танец втроём"
  },
  Event_125722_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 25 чёрных печатей, заразиться «(Skill.Arg2)», продолжить выбор"
  },
  Event_125722_ChoiceDesc2 = {
    Text = "[Пустить на самотёк] покинуть"
  },
  Event_125722_Desc = {
    Text = "«Они танцуют. Они поют. Скрип— скрип—»"
  },
  Event_125722_Name = {
    Text = "Последнее Пророчество"
  },
  Event_125723_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125723_Desc = {
    Text = "Наставник, соратник, единственный спутник в одиноком измерении.\nВы вместе разберётесь со всем, что здесь происходит, и вернётесь в Кадат. Вы никогда в этом не сомневались."
  },
  Event_125723_Name = {
    Text = "Отражение в вине"
  },
  Event_125724_ChoiceDesc1 = {
    Text = "\"Рискнем\" заражает \"(Skill.Arg1)\", вступая в азартную игру"
  },
  Event_125724_ChoiceDesc2 = {
    Text = "\"Ладно, забудем\" получено 25 чёрных печатей"
  },
  Event_125724_Desc = {
    Text = "На углу переулка грязные руки преградили вам путь.\nОборванный нищий тихо подкрался к вам, его взгляд жаден, словно у гиены, завидевшей падаль.\n«Давай! Давай сыграем! Я расскажу тебе всё, что ты хочешь знать! Если только ты выиграешь…»"
  },
  Event_125724_Name = {
    Text = "Уличная ставка"
  },
  Event_125725_ChoiceDesc1 = {
    Text = "[Проигнорировать] Удалить 1 командную карту, получить 25 чёрных печатей"
  },
  Event_125725_ChoiceDesc2 = {
    Text = "[Прочитать]Скопировать одну карту из колоды, заразиться «(Skill.Arg1)»"
  },
  Event_125725_Desc = {
    Text = "Тук-тук-тук, тук-тук-тук…\nВ пустом углу бара звонко стучит телеграфный аппарат, словно изящная фортепианная мелодия."
  },
  Event_125725_Name = {
    Text = "Межпространственная телеграмма"
  },
  Event_125726_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125726_Desc = {
    Text = "«Замолчи, я кошка, и мне не интересны ваши дурацкие истории.»\nЧёрная кошка вздохнула и отвернулась.\n«Уходи отсюда. И больше не делай подобных глупостей.»"
  },
  Event_125726_Name = {
    Text = "Иллюзорное превращение"
  },
  Event_125727_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125727_Desc = {
    Text = "Возможно, она права — это ты, это самые потаённые и грязные мысли в глубине твоей души.\nКаждый эгоистичен, ты никогда не был так благороден, как думали другие.\nТы вкушаешь эту низменную боль. Ты знаешь, что прошлое осталось позади, а твоё искупление — впереди."
  },
  Event_125727_Name = {
    Text = "Распространение боли"
  },
  Event_125728_ChoiceDesc1 = {
    Text = "[Обсудить с ней] Удалить 1 командную карту, получить Arg1 тёмных печатей"
  },
  Event_125728_ChoiceDesc2 = {
    Text = "[Промолчать]"
  },
  Event_125728_Desc = {
    Text = "«Героический финал так реалистичен, но наша действительность и без того жестока — неужели даже в истории мы не можем дать ей счастливый приют…»\nДраматург закрывает глаза в раздумьях. Этот финал её не устраивает."
  },
  Event_125728_Name = {
    Text = "Финал пьесы"
  },
  Event_125729_ChoiceDesc1 = {
    Text = "\"Покинуть\" получить Золотая реликвия \"(RelicConfig.Arg1)\""
  },
  Event_125729_Desc = {
    Text = "Тук-тук-тук, кость возбуждённо пляшет в стаканчике, пляшет до полного изнеможения.\n\n«Почему… почему никто никогда не может выиграть!..»"
  },
  Event_125729_Name = {
    Text = "Уличная ставка"
  },
  Event_125730_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125730_Desc = {
    Text = "Ты осторожно приближаешься к ней и внимательно прислушиваешься.\nБабочка взмахивает крыльями и покидает твою ладонь.\nТы ничего не услышал."
  },
  Event_125730_Name = {
    Text = "Привал бабочки"
  },
  Event_125731_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125731_Desc = {
    Text = "Бабочка невозмутима перед твоими попытками её прогнать.\nОна упрямо преследует твою ладонь, и лишь когда ты в последний раз взмахиваешь рукой, она наконец решает улететь.\nТы немного жалеешь. Может, стоило её послушать?"
  },
  Event_125731_Name = {
    Text = "Привал бабочки"
  },
  Event_125732_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125732_Desc = {
    Text = "Чёрный дым разочарованно дрожит, мучительный крик нищего срывается на хрип.\nКость и нищий исчезли в одно мгновение. В потрёпанной шляпе осталась награда за игру."
  },
  Event_125732_Name = {
    Text = "Уличная ставка"
  },
  Event_125733_ChoiceDesc1 = {
    Text = "[Присоединиться к карнавалу]Заразиться «(Skill.Arg1)», получить проклятую Реликвию – «(RelicConfig.Arg2)»"
  },
  Event_125733_ChoiceDesc2 = {
    Text = "[Остановить музыку] Выбрать 1 Реликвию для уничтожения, получить 1 награду"
  },
  Event_125733_ChoiceDesc3 = {
    Text = "[Закрыть уши] Получить 50 чёрных печатей"
  },
  Event_125733_Desc = {
    Text = "«А! Музыка! Как великое представление может обойтись без музыки!!»\nДисгармоничная симфония зазвучала в разрушенном театре, словно хаотичный карнавал. Актёры из Бездны танцуют и ликуют в этом беспорядочном гимне — это ноты, которыми они живут."
  },
  Event_125733_Name = {
    Text = "Гимн судьбы"
  },
  Event_125734_ChoiceDesc1 = {
    Text = "\"Получить 100 чёрных печатей\""
  },
  Event_125734_ChoiceDesc2 = {
    Text = "[2 случайные Командные карты получают Гриф: «(EnchantConfig.Arg1)»]"
  },
  Event_125734_Desc = {
    Text = "Незримые нити судьбы танцуют среди нот, и в этом хаосе звуков ты постепенно улавливаешь ту чарующую мелодию — да, именно так и должна звучать Колесо Судьбы.\nОтверженные Бездны приветствуют тебя, окружают и увлекают в свой беспорядочный карнавал.\nПоздравляю, счастливый зритель! Теперь ты вместе с актёрами поклонишься судьбе."
  },
  Event_125734_Name = {
    Text = "Гимн судьбы"
  },
  Event_125735_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125735_Desc = {
    Text = "Ты не можешь разобрать смысл этих звуков, но знаешь — они должны прекратиться.\nСеребряный Погоня за светом рассекает воздух, словно обезумевший клинок, и его ритм удивительно совпадает с нотами.\nКогда ты приходишь в себя, музыка уже давно смолкла. Ты больше не слышишь ни звука. Перед тобой лишь тьма, вокруг — лишь Тишь.\nБеспорядочный шум и абсолютная Тишь — что из этого страшнее… Страж?"
  },
  Event_125735_Name = {
    Text = "Гимн судьбы"
  },
  Event_125736_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125736_Desc = {
    Text = "Ты протягиваешь руку, и Глава о бабочке легко садится на неё.\nВерно. Смерть, угасание, быстротечность… Бабочка рождается из кокона, а боль — вечная почва для искусства.\nКак достойный зритель, ты должен понять эту истину."
  },
  Event_125736_Name = {
    Text = "Расцвет в угасании"
  },
  Event_125737_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125737_Desc = {
    Text = "Возможно, это снова какой-то трюк Нефреи. \nБабочка поняла твои слова, в тёмном пространстве раздался её безмолвный вздох. Крылья, струящиеся чёрным липким веществом, затрепетали, и вскоре тяжёлый силуэт бабочки исчез в бескрайней темноте. \nТы больше не сможешь узнать, что она хотела сказать тебе."
  },
  Event_125737_Name = {
    Text = "Остаток жизни бабочки"
  },
  Event_125738_ChoiceDesc1 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_125738_Desc = {
    Text = "Тук-тук-тук, кость возбуждённо пляшет в стаканчике, пляшет до полного изнеможения.\n\n«Почему… почему никто никогда не может выиграть!..»"
  },
  Event_125738_Name = {
    Text = "Уличная ставка"
  },
  Event_125739_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125739_Desc = {
    Text = "Сейчас опасно позволять мыслям бесконтрольно блуждать. Ты покачал головой и поспешно всплыл на поверхность…"
  },
  Event_125739_Name = {
    Text = "Тишина"
  },
  Event_125740_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125740_Desc = {
    Text = "Не всякая музыка нуждается в слушателях, не всякая Колесо Судьбы нуждается в ответах.\nТы крепко зажимаешь уши и покидаешь эту шумную сцену.\nТебе всё ещё любопытен смысл той дисгармоничной мелодии, но ты знаешь — ты сделал единственно верный выбор."
  },
  Event_125740_Name = {
    Text = "Гимн судьбы"
  },
  Event_125741_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125741_Desc = {
    Text = "Серебряный Погоня за светом пронзил иллюзию, и чёрные кошки обратились в лужи чёрной слизи.\nДумали обмануть, приняв облик чёрных кошек? От твоих глаз не скрыться."
  },
  Event_125741_Name = {
    Text = "Иллюзорное превращение"
  },
  Event_125742_ChoiceDesc1 = {
    Text = "[Принять судьбу]Выберите 1 из 3 командных карт, чтобы получить Очарование: «(EnchantConfig.Arg1)»"
  },
  Event_125742_Desc = {
    Text = "«Никто не может по-настоящему противостоять судьбе, дорогой. У нас никогда не было права выбора.»\nЖенский голос стал печальным и далёким. Ты не уверен, обращается ли она к тебе или к чему-то иному."
  },
  Event_125742_Name = {
    Text = "Клетка судьбы"
  },
  Event_125743_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 30 чёрных печатей, заразиться «(Skill.Arg2)», продолжить выбор"
  },
  Event_125743_ChoiceDesc2 = {
    Text = "[Пустить на самотёк] покинуть"
  },
  Event_125743_Desc = {
    Text = "«Марионетки выстраиваются в очередь и вступают в огромную сеть судьбы.»"
  },
  Event_125743_Name = {
    Text = "Последнее Пророчество"
  },
  Event_125744_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125744_Desc = {
    Text = "Ты поднимаешь голову и всматриваешься в водоворот бездны, пытаясь расслышать Пророчество воронов.\nНо вороны ничего не сказали. Под твоим взглядом бездна рассеялась.\nСтая воронов исчезла на краю сцены — там, куда тебе предстоит отправиться."
  },
  Event_125744_Name = {
    Text = "Бездна воронов"
  },
  Event_125745_ChoiceDesc1 = {
    Text = "[Согласиться с бабочками] Удалить 2 карты"
  },
  Event_125745_ChoiceDesc2 = {
    Text = "[Возразить бабочкам]Получить проклятый артефакт «(RelicConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125745_ChoiceDesc3 = {
    Text = "\"Покинуть\"Вы получаете Arg1 чёрную печать"
  },
  Event_125745_Desc = {
    Text = "Занавес сцены колышется на ветру. В чёрной слизи, стекающей с тела, ты видишь стаю бабочек.\n«Истинное искусство всегда расцветает в угасании… Не так ли, Страж?»\nТруп танцовщицы улыбается тебе. Ты слышишь шелест крыльев бабочек."
  },
  Event_125745_Name = {
    Text = "Расцвет в угасании"
  },
  Event_125746_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125746_Desc = {
    Text = "Софистика никогда не собьёт тебя с толку. Ты ясно знаешь, по какому пути идёшь и где твоя конечная цель.\nТернии растворяются внутри тебя. Ты ступаешь на дорогу, как и прежде."
  },
  Event_125746_Name = {
    Text = "Распространение боли"
  },
  Event_125747_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125747_Desc = {
    Text = "Ты отворачиваешься, пытаясь забыть о глазах за спиной. Но обнаруживаешь, что твоё тело уже не подчиняется тебе, как прежде.\nТы знаешь — от этих пристальных взглядов тебе никогда не скрыться."
  },
  Event_125747_Name = {
    Text = "Зрители"
  },
  Event_125748_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125748_Desc = {
    Text = "Независимо от того, из уважения или страха, ты не хочешь легко прикасаться к нему и кладёшь конверт на место. Когда ты собираешься уйти, из темноты за конвертом доносится мутный, но мягкий голос. \n«Спасибо, что помните меня, мисс Арахна...»"
  },
  Event_125748_Name = {
    Text = "Спокойной ночи, мистер Эдгар"
  },
  Event_125749_ChoiceDesc1 = {
    Text = "[Огромная Огромная сила защиты]Получить серебряную Реликвию «(RelicConfig.Arg1)»"
  },
  Event_125749_ChoiceDesc2 = {
    Text = "[Свобода побега]Случайная Карта получает Очарование: «(EnchantConfig.Arg1)»"
  },
  Event_125749_ChoiceDesc3 = {
    Text = "[Отказаться отвечать] Получить 50 чёрных печатей"
  },
  Event_125749_Desc = {
    Text = "Алкоголь из «Полуночной маски» проникает в твою голову, сковывая тебя подобно цепям. Вдоль ледяных звеньев в твоём сознании звучит голос молодой женщины.\n«Скажи мне, дорогой. Какой судьбы ты желаешь на самом деле?»"
  },
  Event_125749_Name = {
    Text = "Замок судьбы"
  },
  Event_125750_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125750_Desc = {
    Text = "Какими бы сложными ни были дела, решать их предстоит вам.\nОщущая нарастающую тяжесть, ты также чувствуешь новую силу."
  },
  Event_125750_Name = {
    Text = "Тишина"
  },
  Event_125751_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125751_Desc = {
    Text = "Неизвестные актёры, опасные па. Верно, бегство — всегда самый безопасный выбор.\nВы разворачиваетесь и бежите, раздвигаете Занавес опускается театра, и вот — вы стоите на сцене. Марионетки берут вас за руки и пускаются в весёлый танец.\nНа сцене судьбы выбора не существует."
  },
  Event_125751_Name = {
    Text = "Танец втроём"
  },
  Event_125752_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125752_Desc = {
    Text = "Сейчас не время смотреть кино."
  },
  Event_125752_Name = {
    Text = "Кинозал воспоминаний"
  },
  Event_125753_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125753_Desc = {
    Text = "Опасности на пути совсем не вошли в твою голову. Ты прошел мимо разрушенной судьбы и продолжил приближаться к Нефрее. \n Ты пришел сюда, чтобы принести ей освобождение."
  },
  Event_125753_Name = {
    Text = "Финал Паутины судьбы"
  },
  Event_125754_ChoiceDesc1 = {
    Text = "[Прочитать конверт]Получить золотую Реликвию «(RelicConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125754_ChoiceDesc2 = {
    Text = "[Прочитать письмо]Выбрать 1 из 3 командных карт для получения Очарования: «(EnchantConfig.Arg1)»"
  },
  Event_125754_ChoiceDesc3 = {
    Text = "[Вернуть на место] получает 50 Черная печать"
  },
  Event_125754_Desc = {
    Text = "Ваши движения разорвали густую паутину, и из неё выпало старое письмо.\nОно весит куда больше, чем тонкий лист бумаги."
  },
  Event_125754_Name = {
    Text = "Спокойной ночи, мистер Эдгар"
  },
  Event_125755_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125755_Desc = {
    Text = "Из глаз ворона падают слёзы. Из клюва ворона течёт кровь. Ворон отдаёт всю свою жизнь, чтобы пропеть тебе своё последнее Пророчество."
  },
  Event_125755_Name = {
    Text = "Последнее Пророчество"
  },
  Event_125756_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125756_Desc = {
    Text = "«Хе-хе… Ха-ха-ха-ха!»\n«Ну как, мой Гость? Вкус судьбы — ты будешь безумно скучать по нему…»"
  },
  Event_125756_Name = {
    Text = "Вкус судьбы"
  },
  Event_125757_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125757_Desc = {
    Text = "«Скучно.» Женский голос лениво зевнул.\n«Забирай свою силу и иди в клуб на бои.»"
  },
  Event_125757_Name = {
    Text = "Замок судьбы"
  },
  Event_125758_ChoiceDesc1 = {
    Text = "[Стабилизировать паутину судьбы] Получить продвинутое клеймо(выбор 1 из 3)"
  },
  Event_125758_ChoiceDesc2 = {
    Text = "[Игнорировать опасность]Получить золотой артефакт «(RelicConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125758_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_125758_Desc = {
    Text = "Она — прекрасная любимица. Она — брошенный судьбой ребенок. Она — мститель, выбравшийся из бездны, следуя тусклым огонькам. Она пришла сюда, чтобы принести освобождение всему. \n Сеть судьбы рушится вокруг вас. Вы стоите на сцене театра, не так далеко от Нефреи."
  },
  Event_125758_Name = {
    Text = "Финал Паутины судьбы"
  },
  Event_125759_ChoiceDesc1 = {
    Text = "[Авидья]Получить серебряный артефакт «(RelicConfig.Arg1)»"
  },
  Event_125759_ChoiceDesc2 = {
    Text = "[Сопереживание]Получить золотой артефакт «(RelicConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125759_Desc = {
    Text = "Со сцены доносятся душераздирающие рыдания, единственный луч света падает на одинокую фигуру.\nОн дарит вам своё самое искреннее представление — вскрывает свои внутренности и показывает их каждому зрителю.\nЧто причиняет этому персонажу такую боль?"
  },
  Event_125759_Name = {
    Text = "Исповедь актёра"
  },
  Event_125760_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125760_Desc = {
    Text = "Ваша рука тянется вправо.\nЭто ваше будущее, ваше самое сильное желание, ваше предназначение, место, куда вы стремитесь.\nВы существуете, чтобы гнаться за солнцем впереди."
  },
  Event_125760_Name = {
    Text = "Прошлое, будущее"
  },
  Event_125761_ChoiceDesc1 = {
    Text = "\"три точки\""
  },
  Event_125761_ChoiceDesc2 = {
    Text = "\"шесть часов\""
  },
  Event_125761_ChoiceDesc3 = {
    Text = "\"одна точка\""
  },
  Event_125761_Desc = {
    Text = "Конечно, вы могли бы просто уйти, но изящная игральная кость полностью завладела вашим вниманием.\nВы забыли о преследователях за спиной, благоговейно подняли её и бросили в шляпу —"
  },
  Event_125761_Name = {
    Text = "Уличная ставка"
  },
  Event_125762_ChoiceDesc1 = {
    Text = "\"Покинуть\" получить серебряное создание \"(RelicConfig.Arg1)\""
  },
  Event_125762_Desc = {
    Text = "Тук-тук-тук, кость возбуждённо пляшет в стаканчике, пляшет до полного изнеможения.\n\n«Почему… почему никто никогда не может выиграть!..»"
  },
  Event_125762_Name = {
    Text = "Уличная ставка"
  },
  Event_125763_ChoiceDesc1 = {
    Text = "[Принять судьбу]Выберите 1 из 3 командных карт, чтобы получить Очарование: «(EnchantConfig.Arg1)»"
  },
  Event_125763_ChoiceDesc2 = {
    Text = "[Противостоять судьбе]Заразиться «(Skill.Arg1)», снова случайно гравировать"
  },
  Event_125763_Desc = {
    Text = "«Ах, шалунишка. Судьба всегда милосердна… Но у любого сопротивления есть цена. Готов ли ты принять её?»"
  },
  Event_125763_Name = {
    Text = "Клетка судьбы"
  },
  Event_125764_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125764_Desc = {
    Text = "Ты оглядываешь все эти взгляды и приветственно машешь им рукой.\nСовсем скоро ты подаришь им кульминацию этой истории."
  },
  Event_125764_Name = {
    Text = "Зрители"
  },
  Event_125765_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125765_Desc = {
    Text = "«Дорогая мисс Арахна, сегодня день вашего рождения, и я рад за хозяина и хозяйку, а также за вас. Добро пожаловать в этот прекрасный мир. Я посвящаю вам эту нежную колыбельную, пусть с этого дня вашей жизни вы проведете беззаботно...»"
  },
  Event_125765_Name = {
    Text = "Спокойной ночи, мистер Эдгар"
  },
  Event_125766_ChoiceDesc1 = {
    Text = "[Сделать фото]Выберите 1 из 3 командных карт, чтобы получить Очарование: «(EnchantConfig.Arg1)»"
  },
  Event_125766_ChoiceDesc2 = {
    Text = "[Сменить ещё раз]Заражение «(Skill.Arg1)», сменить Очарование из варианта 1, можно использовать ещё один раз"
  },
  Event_125766_Desc = {
    Text = "Перед объективом тебя охватывает Тревога. Может, в этой позе снимок выйдет лучше? Или в той?"
  },
  Event_125766_Name = {
    Text = "Снимок из зрительного зала"
  },
  Event_125767_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125767_Desc = {
    Text = "Ты хочешь увидеть, что на экране, но на полотне ничего нет — в зале лишь эхо вращающейся плёнки.\nВозможно, лишь спустя долгое время тебе удастся узнать, что скрывает эта плёнка."
  },
  Event_125767_Name = {
    Text = "Кинозал воспоминаний"
  },
  Event_125768_ChoiceDesc1 = {
    Text = "\"Избегание взгляда\" случайно пробуждает 1 пробуждающее тело"
  },
  Event_125768_ChoiceDesc2 = {
    Text = "\"Прямой взгляд\"Выберите пробуждающее тело и уменьшите расход вычислительной мощности его карты пробуждения на 2. Заразить \"(Skill.Arg1)\""
  },
  Event_125768_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_125768_Desc = {
    Text = "Ступив на сцену, ты слышишь шёпот. Ты оборачиваешься — десять тысяч глаз зрителей парят вокруг сцены, пристально глядя на тебя.\nДавай! — говорят они. — Неужели великолепная пьеса остановится здесь?\nТанцуй! — говорят они. — Подари нам кульминацию этого танца!"
  },
  Event_125768_Name = {
    Text = "Зрители"
  },
  Event_125769_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125769_Desc = {
    Text = "Вы не понимаете его боли и не нуждаетесь в этом.\nВ театре так много сцен, на сценах так много марионеток, и вы — лишь одна из них.\nУ вас есть дела поважнее."
  },
  Event_125769_Name = {
    Text = "Исповедь актёра"
  },
  Event_125770_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125770_Desc = {
    Text = "Смерть, угасание, быстротечность… Искусство существует не для того, чтобы причинять боль. Если красота существует лишь в страдании, то такая красота не нужна.\nТы изо всех сил отгоняешь их. Бабочки разлетаются, оставляя печальное тело."
  },
  Event_125770_Name = {
    Text = "Расцвет в угасании"
  },
  Event_125771_ChoiceDesc1 = {
    Text = "[Слушать пение]Получить 40 чёрных печатей, заразиться «(Skill.Arg2)», продолжить выбор"
  },
  Event_125771_ChoiceDesc2 = {
    Text = "\"Оставить как есть\" получить 25 чёрных печатей и покинуть"
  },
  Event_125771_Desc = {
    Text = "Стаи ворон, что встречались тебе прежде, слились в одну. Она стоит перед тобой и поёт, и песня её печальна, словно последнее Пророчество."
  },
  Event_125771_Name = {
    Text = "Последнее Пророчество"
  },
  Event_125772_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125772_Desc = {
    Text = "Ваша рука тянется влево.\nЭто ваше прошлое, ваши самые драгоценные воспоминания, путь, которым вы пришли, место, куда вы вернётесь.\nВсё, что было прежде, составляет всю вашу суть."
  },
  Event_125772_Name = {
    Text = "Прошлое, будущее"
  },
  Event_125773_ChoiceDesc1 = {
    Text = "[Сделать фото]Выберите 1 из 3 командных карт, чтобы получить Очарование: «(EnchantConfig.Arg1)»"
  },
  Event_125773_Desc = {
    Text = "Перед объективом тебя охватывает Тревога. Может, в этой позе снимок выйдет лучше? Или в той?\nТы всё ещё колеблешься, но замечаешь, что камера уже сильно раздражена."
  },
  Event_125773_Name = {
    Text = "Снимок из зрительного зала"
  },
  Event_125774_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125774_Desc = {
    Text = "Ты принимаешь позу и встаёшь перед камерой. Прямо, с любопытством, с полной отдачей — как Реальность зритель.\nЩёлк—\nКамера нажимает на затвор, чёрная вязкая жижа взрывается из корпуса и разбрызгивается по всей сцене.\nВ центре останков камеры плёнка абсолютно пуста."
  },
  Event_125774_Name = {
    Text = "Снимок из зрительного зала"
  },
  Event_125775_ChoiceDesc1 = {
    Text = "[Принять] Получить серебряный артефакт(выбор 1 из 3)"
  },
  Event_125775_ChoiceDesc2 = {
    Text = "[Сбежать]Получить серебряные артефакты «(RelicConfig.Arg1)» «(RelicConfig.Arg2)», заразиться дважды «(Skill.Arg3)»"
  },
  Event_125775_Desc = {
    Text = "Тук-тук, тук-тук… Каблуки ударяются о доски, издавая радостный звонкий стук.\nДве марионетки в школьной форме танцуют на сцене. Внезапно они останавливаются и протягивают вам руки."
  },
  Event_125775_Name = {
    Text = "Танец втроём"
  },
  Event_125776_ChoiceDesc1 = {
    Text = "[Вытерпеть боль] Увеличить максимальное здоровье на Arg1"
  },
  Event_125776_ChoiceDesc2 = {
    Text = "[Возразить боли] 1 случайная Командная карта получает Гриф: «(EnchantConfig.Arg1)», заразить 1 карту «(Skill.Arg2)»"
  },
  Event_125776_Desc = {
    Text = "«Тебе никогда не было дела до смерти Лиз. Тебе никогда не было дела ни до кого.»\n«Тебя заботишь только ты сам… Все вокруг тебя — лишь инструменты на пути к свободе и покою.»\n«Разве не так… Страж?»\nШёпот конферансье звучит у тебя в ушах. Твоё сердце сжимается, и жгучая боль расползается по телу вслед за её словами…"
  },
  Event_125776_Name = {
    Text = "Распространение боли"
  },
  Event_125777_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125777_Desc = {
    Text = "Отдайся погружению сознания — вода сама удержит на плаву, а Колесо Судьбы укажет вам путь ко всему."
  },
  Event_125777_Name = {
    Text = "Тишина"
  },
  Event_125778_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125778_Desc = {
    Text = "Это вы сами. Источник силы, носитель долга, единственный объект верности.\nВы идёте по дороге, которая принадлежит только вам."
  },
  Event_125778_Name = {
    Text = "Отражение в вине"
  },
  Event_125779_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125779_Desc = {
    Text = "«Как жаль, мой Гость. Вкус судьбы тебе больше никогда не доведётся испробовать…»"
  },
  Event_125779_Name = {
    Text = "Вкус судьбы"
  },
  Event_125780_ChoiceDesc1 = {
    Text = "[Обсудить с ней] Удалить 1 командную карту, получить Arg1 тёмных печатей"
  },
  Event_125780_ChoiceDesc2 = {
    Text = "[Промолчать]"
  },
  Event_125780_Desc = {
    Text = "«Какая печальная пьеса… Эту бедную девочку бросил тот, кого она любила, сестра?»\nВ этом знакомом голосе ты не слышишь ни безумия, ни ненависти. Голос чист и печален, словно нежный Ручей в лесной чаще.\n«Та певица — бессильный увядший лист, отданный на растерзание судьбе… Какая жалость…»\n«Скажи, если бы я была тем, кто держит перо… Какой финал мне следовало бы написать для неё?»"
  },
  Event_125780_Name = {
    Text = "Финал пьесы"
  },
  Event_125781_ChoiceDesc1 = {
    Text = "[Погладить]50% шанс получить 125 чёрных печатей, 50% шанс заразиться «(Skill.Arg2)»"
  },
  Event_125781_ChoiceDesc2 = {
    Text = "[Объяснить]75% шанс получить 100 чёрных печатей, 25% шанс заразиться «(Skill.Arg2)»"
  },
  Event_125781_ChoiceDesc3 = {
    Text = "[Разгадать] Получить 50 чёрных печатей"
  },
  Event_125781_Desc = {
    Text = "Когда ты бросился в переулок за баром, силуэт чудовища исчез, и стая чёрных кошек преградила тебе путь.\n«Эй, ты.» Одна чёрная кошка облизала свою лапу и посмотрела на тебя.\n«Что ты делаешь на нашей территории?»"
  },
  Event_125781_Name = {
    Text = "Иллюзорное превращение"
  },
  Event_125782_ChoiceDesc1 = {
    Text = "[Обнять прошлое]Получить золотой артефакт «(RelicConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125782_ChoiceDesc2 = {
    Text = "[Встретить будущее]Получить золотой артефакт (выбор 1 из 3), заразиться «(Skill.Arg1)»"
  },
  Event_125782_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить серебряное создание \"(RelicConfig.Arg1)\""
  },
  Event_125782_Desc = {
    Text = "Появление Нефреи помешало нитям. В хаосе судьбы ты видишь два размытых фантома. \nЭто твоё прошлое, это твоё будущее. Ты подходишь к ним и протягиваешь руку..."
  },
  Event_125782_Name = {
    Text = "Прошлое, будущее"
  },
  Event_125855_ChoiceDesc1 = {
    Text = "[Ощутить]Выбрать 1 артефакт и превратить его в золотой артефакт «(RelicConfig.Arg1)»"
  },
  Event_125855_ChoiceDesc2 = {
    Text = "\"взор\" получает Серебряная реликвия \"(RelicConfig.Arg1)\", инфекция \"(Skill.Arg2)\""
  },
  Event_125855_ChoiceDesc3 = {
    Text = "\"игнорировать\" получить 25 чёрных печатей"
  },
  Event_125855_Desc = {
    Text = "На улицах Кассалима ослепительное сияние лавки кристаллов привлекло ваше внимание. Вы подходите к лавке и поднимаете кристалл в форме серебряного ядра."
  },
  Event_125855_Name = {
    Text = "Тайна кристалла"
  },
  Event_125856_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125856_Desc = {
    Text = "Вы закрываете глаза и внимательно вслушиваетесь в его суть.\nСлабый Погоня за светом мерцает в вашем сознании — он хочет что-то вам сказать…"
  },
  Event_125856_Name = {
    Text = "Тайна кристалла"
  },
  Event_125857_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125857_Desc = {
    Text = "Любое сопротивление судьбе и попытки заглянуть в неё тщетны. Ты тихо закрываешь глаза, позволяя судьбе унести тебя туда, куда ей угодно."
  },
  Event_125857_Name = {
    Text = "Сеть пленённой судьбы"
  },
  Event_125858_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125858_Desc = {
    Text = "«Чувства — это смысл существования. Будем надеяться, что ты не пожалеешь о своём выборе.»"
  },
  Event_125858_Name = {
    Text = "Плата выбора"
  },
  Event_125859_ChoiceDesc1 = {
    Text = "[Чувства] Восстановить Arg1 ед. здоровья"
  },
  Event_125859_ChoiceDesc2 = {
    Text = "[Рассудок]Случайная командная Карта получает клеймо: «(EnchantConfig.Arg1)»"
  },
  Event_125859_ChoiceDesc3 = {
    Text = "[Отказаться выбирать] получает 25 Черная печать"
  },
  Event_125859_Desc = {
    Text = "На сцене появляются весы.\n«Разум и сердце, рассудок и чувства, серое и красное… Мы не можем избежать выбора — такова наша Колесо Судьбы.»\n«Конечная точка сцены уже определена. Теперь выбери путь, по которому эта сцена пойдёт.»"
  },
  Event_125859_Name = {
    Text = "Плата выбора"
  },
  Event_125860_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125860_Desc = {
    Text = "«Не поднимай голову. Уходи отсюда.»\nВы слышите голос судьбы. Вам невыносимо хочется взглянуть на небо, но вы знаете — она права."
  },
  Event_125860_Name = {
    Text = "Взгляд ввысь"
  },
  Event_125861_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125861_Desc = {
    Text = "Ты никогда не примешь судьбу. Ты никогда не примешь заточение.\nТы отчаянно сопротивляешься, и, пожертвовав частью тела мотылька, наконец вырываешься на свободу…"
  },
  Event_125861_Name = {
    Text = "Сеть пленённой судьбы"
  },
  Event_125862_ChoiceDesc1 = {
    Text = "[Дружба] Получить 50 чёрных печатей"
  },
  Event_125862_ChoiceDesc2 = {
    Text = "[Помощь]Получить 75 чёрных печатей, заразиться «(Skill.Arg2)»"
  },
  Event_125862_Desc = {
    Text = "На задворках бара ты снова встречаешь тех чёрных кошек.\n«Я слышал. Эта чёрная слизь приняла наш облик и доставила тебе немало хлопот.»\n«В качестве извинения — скажи мне, чего ты хочешь?»\nЧёрная кошка дважды обходит вокруг твоих ног и поднимает на тебя взгляд."
  },
  Event_125862_Name = {
    Text = "Подарок при первой встрече"
  },
  Event_125863_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125863_Desc = {
    Text = "Грубая Огромная Огромная сила не разгадает судьбу, но, быть может, мудрость сможет?\nТы внимательно изучаешь эту сеть, пытаясь разглядеть в ней нити судьбы…"
  },
  Event_125863_Name = {
    Text = "Сеть пленённой судьбы"
  },
  Event_125864_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125864_Desc = {
    Text = "Вы наклоняетесь ближе и пристально вглядываетесь в него.\nСлабый Погоня за светом мерцает в ваших глазах — он хочет что-то вам сказать…"
  },
  Event_125864_Name = {
    Text = "Тайна кристалла"
  },
  Event_125865_ChoiceDesc1 = {
    Text = "[Сопротивляться] Случайно получить 3 командные карты из колоды, выбрать 1 карту для удаления, получить 75 чёрных печатей"
  },
  Event_125865_ChoiceDesc2 = {
    Text = "[Обдумать] Случайно получить 3 командные карты из колоды, оригинальная Копия 1 выбранной карты добавляется в колоду, получить 25 чёрных печатей"
  },
  Event_125865_ChoiceDesc3 = {
    Text = "[Отдохнуть] Получить 50 чёрных печатей"
  },
  Event_125865_Desc = {
    Text = "Знакомое ощущение нахлынуло на тебя, но на этот раз липкое прикосновение и инстинктивная беспомощность стали сильнее и смертоноснее, чем прежде.\nМотылёк падает в паутину, а ты уже ступил на сцену."
  },
  Event_125865_Name = {
    Text = "Сеть пленённой судьбы"
  },
  Event_125866_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125866_Desc = {
    Text = "«Разум — средство выживания. Надеюсь, ты не пожалеешь о своём выборе.»"
  },
  Event_125866_Name = {
    Text = "Плата выбора"
  },
  Event_125867_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125867_Desc = {
    Text = "Любопытство разгорелось. Вы входите в толпу и, подобно остальным, поднимаете голову.\nТам ничего нет, но почему-то вы не можете отвести взгляд. Вам хочется смотреть вот так, смотреть бесконечно…"
  },
  Event_125867_Name = {
    Text = "Взгляд ввысь"
  },
  Event_125868_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125868_Desc = {
    Text = "«Отказ от выбора — тоже выбор, таково проклятие судьбы. Надеюсь, ты не пожалеешь о своём выборе.»"
  },
  Event_125868_Name = {
    Text = "Плата выбора"
  },
  Event_125869_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125869_Desc = {
    Text = "«Теперь это принадлежит тебе.»\nЧёрная кошка потёрлась о твою голень и быстро исчезла.\nТам, где она исчезла, тебя ждёт Подарок."
  },
  Event_125869_Name = {
    Text = "Подарок при первой встрече"
  },
  Event_125870_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_125870_Desc = {
    Text = "«Теперь это принадлежит тебе.»\nЧёрная кошка потёрлась о твою голень и быстро исчезла.\nТам, где она исчезла, тебя ждёт Подарок."
  },
  Event_125870_Name = {
    Text = "Подарок при первой встрече"
  },
  Event_125871_ChoiceDesc1 = {
    Text = "[Поднять голову] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)», заразиться «(Skill.Arg2)»"
  },
  Event_125871_ChoiceDesc2 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_125871_Desc = {
    Text = "Шум на мгновение стих. Орден разбухшей благодати на улице замолкла и подняла глаза к небу."
  },
  Event_125871_Name = {
    Text = "Взгляд ввысь"
  },
  Event_129176_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129176_Name = {
    Text = "Забвение глава 1@"
  },
  Event_129177_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129177_Name = {
    Text = "Звёздное Царство 1@"
  },
  Event_129178_ChoiceDesc1 = {
    Text = "\"Указание направления\"получить Серебряная реликвия \"(RelicConfig.Arg1)\", Погружение \"(Skill.Arg2)\""
  },
  Event_129178_ChoiceDesc2 = {
    Text = "[Молиться вместе] Получить гриф на выбор из 3, повторить 2 раза"
  },
  Event_129178_Desc = {
    Text = "Звуки пианино и органа переплетаются в сером ветре. Как будто волшебная мелодия кружит по безлюдным улицам. \n Безымянная монахиня молится под звуки музыки. \n \"Простая Текст молитвы не требует торжественной церемонии, великий Бог-Отец будет Развеивание надежду, как Он когда-то даровал нам благочестивое наставление.\""
  },
  Event_129178_Name = {
    Text = "Органная Текст молитвы"
  },
  Event_129179_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129179_Name = {
    Text = "Звёздное Царство 1@"
  },
  Event_129180_ChoiceDesc1 = {
    Text = "\"Активная атака\": Получить проклятое создание \"(RelicConfig.Arg1)\", Погружение \"(Skill.Arg2)\""
  },
  Event_129180_ChoiceDesc2 = {
    Text = "[Прекратить сопротивление] Выбрать 1 из 3 Командных карт и получить Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129180_ChoiceDesc3 = {
    Text = "\"Срочно смыться\" получить 50 чёрных печатей"
  },
  Event_129180_Desc = {
    Text = "Несколько восковых глиняных заготовок преградили вам путь. \n Они искривлены, лица грубые, выглядят не на уровне мастерства, которого следует ожидать от Роджерса. \n \"Приказ... приказ господина...\""
  },
  Event_129180_Name = {Text = "Этюд"},
  Event_129181_ChoiceDesc1 = {
    Text = "\"Отказаться от мысли\" получить Проклятая реликвия \"(RelicConfig.Arg1)\", заразиться \"(Skill.Arg2)\""
  },
  Event_129181_ChoiceDesc2 = {
    Text = "[Поймать озарение] Случайная 1 командная карта получает гриф: [(EnchantConfig.Arg1)], повторить 2 раза"
  },
  Event_129181_Desc = {
    Text = "Порт подвергся атаке, мистальный грузовой корабль без возврата и \"новые друзья\" с плавниками... Это тщательно подготовленная ловушка? Или ещё одно путешествие, полное неожиданностей? \n Реальность и разум взаимно тянут Близкий Близкий Близкий Близкий друг друга, бесчисленные озарения и мысли хлынут из головы."
  },
  Event_129181_Name = {
    Text = "Вспышка вдохновения"
  },
  Event_129182_ChoiceDesc1 = {
    Text = "[Присоединиться] Заражает «(Skill.Arg1)» дважды, случайная 1 Карта получает Гриф: «(EnchantConfig.Arg2)» дважды"
  },
  Event_129182_ChoiceDesc2 = {
    Text = "[Прогнать] Заражает «(Skill.Arg1)» дважды, случайная 1 Карта получает Гриф: «(EnchantConfig.Arg2)» дважды"
  },
  Event_129182_ChoiceDesc3 = {
    Text = "[Игнорировать] Выбрать 1 из 3 Командных карт, которая получает Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129182_Desc = {
    Text = "Вы слышите вдали неясный звук костяного рога. \nСтадо мышей, следуя звуку, появляется из черной грязи, поедая безымянные тела, лежащие на высохлом русле реки. \nОни образуют круг, в центре которого находится уже пустое тело, а окружность представляет собой новое королевство, основанное на забвении. \nА вы стоите у входа в это королевство."
  },
  Event_129182_Name = {
    Text = "Изгнанное Королевство"
  },
  Event_129183_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129183_Name = {
    Text = "Забвение Глава 5@"
  },
  Event_129184_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129184_Name = {
    Text = "Забвение глава 8@"
  },
  Event_129185_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129185_Name = {
    Text = "Забвение глава 1@"
  },
  Event_129186_ChoiceDesc1 = {
    Text = "[Спасти портрет] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)» дважды, заражает «(Skill.Arg2)» дважды"
  },
  Event_129186_ChoiceDesc2 = {
    Text = "[Принять пустоту] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)» дважды, заражает «(Skill.Arg2)» дважды"
  },
  Event_129186_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129186_Desc = {
    Text = "Ты стоишь перед даром Пикмана. \n Это портрет, написанный кровью, черные пламя тихо горит. \n Сквозь пустые глазницы человека на картине ты видишь — \n твои воспоминания бурлят и горят, растягиваются, искажаются, светятся, как будто некий невидимый Искра лизал коридоры в твоем мозгу. В замешательстве ты слышишь чей-то голос. \n \"Время класть в кастрюлю, температура идеальна.\" \n Это именно то, что ты сам нарисовал в своих воспоминаниях, ты борешься и искажаешься в огне."
  },
  Event_129186_Name = {
    Text = "Сожженный портрет"
  },
  Event_129187_ChoiceDesc1 = {
    Text = "[Какую цену вы готовы заплатить?] Случайно повысить качество Грифа 1 Карты дважды"
  },
  Event_129187_ChoiceDesc2 = {
    Text = "[Угостить их стаканом просроченной Кровавой Мэри] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129187_Desc = {
    Text = "\"Добро пожаловать, мой драгоценный Гость. Не стесняйтесь выбирать, всё это великолепие существует ради вас.\"\n\"Эм, извините, могу я спросить, вы... сестра-близнец леди Давдейл?\"\n\"Я сама леди Давдейл. Позвольте спросить, с какой целью вы сегодня пришли...?\"\n\"Извините, извините, вы стали ещё более очаровательной, я даже не узнал вас. Вы помните? Двадцать лет назад вы прогнали чудовище из моего бара... Вчера Повторение кошмара, оно захватило бар вместе со своими сородичами, целыми толпами...\""
  },
  Event_129187_Name = {
    Text = "Фрагмент воспоминания · Воспроизведение старых снов"
  },
  Event_129188_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129188_Name = {
    Text = "Глава 3 звёзд@"
  },
  Event_129189_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129189_Name = {
    Text = "Забвение глава 8@"
  },
  Event_129190_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129190_Name = {
    Text = "Забвение глава 1@"
  },
  Event_129191_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129191_Name = {
    Text = "Забвение глава 6@"
  },
  Event_129192_ChoiceDesc1 = {
    Text = "[Сжимая Искра] увеличивает максимальное здоровье на Arg1 пунктов"
  },
  Event_129192_ChoiceDesc2 = {
    Text = "[Взглянуть в лицо себе] Случайные 2 командные карты получают гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заразить 2 карты «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129192_Desc = {
    Text = "В этой грандиозной охоте Погоня Голиафа было как зверь в темной ночи, стремящийся поглотить Погоня за светом всякой надежды. Однако это беспощадное Погоня не заморозило тебя, а наоборот, разожгло Искра в глубине души, который распространился и сжигал в груди, становясь всё более горячим."
  },
  Event_129192_Name = {
    Text = "Погоня за светом"
  },
  Event_129193_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129193_Name = {
    Text = "Забвение глава 6@"
  },
  Event_129194_ChoiceDesc1 = {
    Text = "[Читать Путь предшественников] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)», заражение «(Skill.Arg2)»"
  },
  Event_129194_ChoiceDesc2 = {
    Text = "\"пиши свою дорогу\"получить создание из серебра\"(RelicConfig.Arg1)\", Погружение\"(Skill.Arg2)\""
  },
  Event_129194_ChoiceDesc3 = {
    Text = "\"Взгляд в Мрак\"получить 25 чёрные Печать пакиа"
  },
  Event_129194_Desc = {
    Text = "Если бы ты одинокий блуждал в мистическом мире, ты бы не был так уверен в своем пути, как сейчас. \n Следы в мистическом мире разделились на три пути, каждый Отпечаток несет в себе невидимое будущее."
  },
  Event_129194_Name = {Text = "Выход"},
  Event_129195_ChoiceDesc1 = {
    Text = "[Указать на ошибку] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129195_ChoiceDesc2 = {
    Text = "\"После прослушивания исполнения\"за каждое пробуждающее тело с уровнем безумия 50 и выше, получите 15 чёрных печатей"
  },
  Event_129195_ChoiceDesc3 = {
    Text = "\"Покинуть\" выбрать гравировку из 3 вариантов"
  },
  Event_129195_Desc = {
    Text = "Мальчик-восковая фигура сидит перед пианино и играет этюды. \n Его учитель — тоже восковая фигура — стоит рядом и даёт указания. \n 133, 355, 244... \n Ошибка, каждая нота неверна."
  },
  Event_129195_Name = {
    Text = "Урок пианино"
  },
  Event_129196_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129196_Name = {
    Text = "Забвение Глава 5@"
  },
  Event_129197_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129197_Name = {
    Text = "Звёздное Царство 4@"
  },
  Event_129198_ChoiceDesc1 = {
    Text = "[Слушать печаль] Выбрать 1 из 3 командных карт, получить гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заразить «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129198_ChoiceDesc2 = {
    Text = "\"Слушай радость\"За каждое пробуждающее тело с очагом ярости 50 и выше — 15 чёрных печатей"
  },
  Event_129198_ChoiceDesc3 = {
    Text = "[Уйти] Получить гриф 3 на выбор дважды"
  },
  Event_129198_Desc = {
    Text = "Мелодия, полная лирики, радости и печали... Звучит в пространстве мистического мира, трудно определить её Генезис. \n Это соната, вытекающая из звуков призрачного корабля, или же это ночная фантазия, связанная в мистическом мире?"
  },
  Event_129198_Name = {
    Text = "Безымянное эхо"
  },
  Event_129199_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129199_Name = {
    Text = "Звёздное Царство 1@"
  },
  Event_129200_ChoiceDesc1 = {
    Text = "[Открыть конверт]получает Золотая реликвия「(RelicConfig.Arg1)», заразится「(Skill.Arg2)」"
  },
  Event_129200_ChoiceDesc2 = {
    Text = "[Прочитать] Выбрать 1 из 3 Командных карт и получить Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129200_ChoiceDesc3 = {
    Text = "[Вернуть на место] получает 50 Черная печать"
  },
  Event_129200_Desc = {
    Text = "В уголке, не привлекающем никого, валялась записка.\nМногое на письме уже неразборчиво, но лишь одно слово. Проникает через бумагу.\nЭто слово - «Матушка»."
  },
  Event_129200_Name = {
    Text = "Угасающие мысли"
  },
  Event_129201_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129201_Name = {
    Text = "Звёздное Царство 4@"
  },
  Event_129202_ChoiceDesc1 = {
    Text = "[Внимательно слушать] Выбрать 1 из 3 командных карт, получить гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заразить «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129202_ChoiceDesc2 = {
    Text = "\"Закрыть уши\"За каждого пробуждающего тела с очагом ярости 50 и выше, получить 15 чёрных печатей"
  },
  Event_129202_ChoiceDesc3 = {
    Text = "[Осмотреть] Получить гриф на выбор из 3, повторить 2 раза"
  },
  Event_129202_Desc = {
    Text = "Когда вы вошли на этаж с останками, в пустом заброшенном заводе неожиданно раздался приятный звук динь-дон, мелодия пианино контрастировала с ржавыми сталелитейными развалинами."
  },
  Event_129202_Name = {
    Text = "Жуткая гамма"
  },
  Event_129203_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129203_Name = {
    Text = "Забвение третья глава@"
  },
  Event_129204_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129204_Name = {
    Text = "Забвение глава 6@"
  },
  Event_129205_ChoiceDesc1 = {
    Text = "\"Отпусти её\"получить проклятое создание\"(RelicConfig.Arg1)\", инфекция\"(Skill.Arg2)\""
  },
  Event_129205_ChoiceDesc2 = {
    Text = "[Помочь ей] Выбрать 1 из 3 Командных карт и получить Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129205_ChoiceDesc3 = {
    Text = "\"Я хочу идти своим путём\" Вы получили 50 чёрных печатей"
  },
  Event_129205_Desc = {
    Text = "Три фигуры преградили тебе путь. \n\"Ты можешь её освободить,\"сказала фигура, держащая игрушечного медведя, покрытого растворенной лавой, \"она просто испугана, а не зла. Она не хочет никому причинять вред.\"\n\"Ты можешь ей помочь,\"сказала фигура, держащая изящно упакованные конфеты, \"ты можешь сделать то, что она не может, ты можешь положить этому Конец.\"\n\"Тебе не обязательно нас слушать,\"сказала фигура с пустыми руками, \"у тебя есть свой путь.\""
  },
  Event_129205_Name = {
    Text = "Разветвлённая тропинка"
  },
  Event_129206_ChoiceDesc1 = {
    Text = "[Покормить крыс]получить серебряное создание «(RelicConfig.Arg1)», выбрать 1 симптом заражения"
  },
  Event_129206_ChoiceDesc2 = {
    Text = "[Прогнать крыс] Выбрать 1 из 3 командных карт, чтобы получить гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заразиться «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129206_ChoiceDesc3 = {
    Text = "[Игнорировать крыс] получить 25 чёрных печатей"
  },
  Event_129206_Desc = {
    Text = "Всё на этом корабле пребывает в круговороте перерождений.\nТе мерзкие, покрытые грязным пухом маленькие создания, что промышляют на борту, тоже не могут избежать этой участи.\nРаз за разом, цикл за циклом, они пожирают всё, что видят, но так и не могут насытиться.\n«Так… голодно…»\nСтаи крыс издают болезненный пронзительный визг.\nБесконечные перерождения довели их до невыносимого голода — они должны что-нибудь съесть.\nНемедленно, сейчас же!"
  },
  Event_129206_Name = {
    Text = "Голодная стая крыс"
  },
  Event_129207_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129207_Name = {
    Text = "Забвение глава 8@"
  },
  Event_129208_ChoiceDesc1 = {
    Text = "[Прикоснуться к мозгу] Случайная 1 Командная карта получает Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129208_ChoiceDesc2 = {
    Text = "[Коснуться сердца]Увеличивает Arg1 очков максимальной жизни, заражая「(Skill.Arg2)」"
  },
  Event_129208_Desc = {
    Text = "Ты входишь в серый зал, где никто не шепчет, и весы едва видны в черном тумане. \n Слева находится спокойный, как озеро, мозг, серебристые борозды которого мерцают слабым светом; справа — огненно-красное сердце, испускающее пар. \n Внезапно ты ощущаешь аромат, жажда разрастается, а разум сжимается в бескрайнем мраке. \n Ты протягиваешь руку."
  },
  Event_129208_Name = {
    Text = "Голодные игры"
  },
  Event_129209_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129209_Name = {
    Text = "Забвение глава 4@"
  },
  Event_129210_ChoiceDesc1 = {
    Text = "[Срубить тень] Выбрать 1 из 3 командных карт, получить гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заразить «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129210_ChoiceDesc2 = {
    Text = "[Раздавить зародыш] Выбрать 1 из 3 командных карт, получить гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заразить «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129210_ChoiceDesc3 = {
    Text = "\"Закрой глаза\"и получи 25 чёрных печатей"
  },
  Event_129210_Desc = {
    Text = "В замешательстве ты видишь людей, которых когда-то встречал среди арамеев, приближающихся к тебе. \n Они смеются и приглашают тебя выпить, потанцевать и отведать угощений. \n Затем их Каро слоями облезают, а упавшие на землю продолжают извиваться, вырастая в новые эмбрионы. \n Они протягивают к тебе руки, приглашая тебя присоединиться к безумию мяса и новорождённых."
  },
  Event_129210_Name = {
    Text = "Тени прошлого"
  },
  Event_129211_ChoiceDesc1 = {
    Text = "[Кормление их]получает Серебряная реликвия「(RelicConfig.Arg1)», выбирает заразиться 1 раз Симптомом"
  },
  Event_129211_ChoiceDesc2 = {
    Text = "[Не обращать внимания] Выбрать 1 из 3 командных карт, получить гриф: «(EnchantConfig.Arg1)» дважды, заразить «(Skill.Arg2)» дважды"
  },
  Event_129211_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129211_Desc = {
    Text = "Жители приходят и уходят, а стая крыс остается на долгое время. \n В сравнении с людьми, они настоящие \"коренные Граждане\" этого замка. \n Но они не возражают против присутствия людей. \n Потому что эти мягкие, белые, уродливые существа будут подкармливать их такими же мягкими, белыми, уродливыми существами. \n \"А ты, уродливое создание, к какому виду принадлежишь?\""
  },
  Event_129211_Name = {
    Text = "Тайна старинного замка"
  },
  Event_129212_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129212_Name = {
    Text = "Забвение Глава 5@"
  },
  Event_129213_ChoiceDesc1 = {
    Text = "\"Различение мужского звука\"Получите 3 случайные карты команды из колоды и выберите 1 для копирования"
  },
  Event_129213_ChoiceDesc2 = {
    Text = "[Распознать голос женщины] Выбрать 1 из 3 командных карт, получить гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заразить «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129213_ChoiceDesc3 = {
    Text = "\"Различение звука старика\"получить 25 чёрных печатей"
  },
  Event_129213_Desc = {
    Text = "Ты одиноко стоишь в тёмном болоте.\nВ смутном состоянии ты слышишь, как хаотичное шептание, как прилив, накатывает на тебя: некоторые из них исходят от стариков, достигших преклонного возраста, некоторые — от детей, едва начинающих говорить, некоторые — от тревожных женщин, некоторые — от мужчин, охваченных необъяснимым страхом..."
  },
  Event_129213_Name = {
    Text = "Предсмертный Бред"
  },
  Event_129214_ChoiceDesc1 = {
    Text = "[Осмотреться внимательно] Получить Гриф на выбор из 3 дважды"
  },
  Event_129214_ChoiceDesc2 = {
    Text = "[Сорвать плакат] Случайная 1 Командная карта получает Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129214_Desc = {
    Text = "Свечной подсвечник, который можно увидеть повсюду в музее восковых фигур.\nВ нездоровом оранжевом свете вы замечаете нарисованный плакат на стене."
  },
  Event_129214_Name = {
    Text = "Смех во тьме"
  },
  Event_129215_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129215_Name = {
    Text = "Забвение глава 4@"
  },
  Event_129216_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129216_Name = {
    Text = "Забвение глава 7@"
  },
  Event_129217_ChoiceDesc1 = {
    Text = "\"взор\" получает Серебряная реликвия \"(RelicConfig.Arg1)\", инфекция \"(Skill.Arg2)\""
  },
  Event_129217_ChoiceDesc2 = {
    Text = "[Игнорировать] Получить гриф на выбор из 3, повторить 2 раза"
  },
  Event_129217_Desc = {
    Text = "Арамеи на коленях в песчаной буре.\nШторм бьёт их тела, песчинки сметают их Преданность.\nВ вихре песка, кажется, множество гигантских глаз смотрят на искажённую Землю."
  },
  Event_129217_Name = {
    Text = "Песчаный гигант"
  },
  Event_129218_ChoiceDesc1 = {
    Text = "[Прогнать Бабочку] Случайная 1 Командная карта получает Гриф: «(EnchantConfig.Arg1)» дважды, заражает «(Skill.Arg2)» дважды"
  },
  Event_129218_ChoiceDesc2 = {
    Text = "[Выслушать желание] Выбрать 1 из 3 Командных карт, которая получает Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129218_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129218_Desc = {
    Text = "Маленькая Глава о бабочке тоже имеет множество мечт.\nЭти мечты разбросаны по цветочным полям, больничным палатам и полным мяса и крови @2алтарям.\nИ вот, она наконец дождалась человека, к которому привязалась, не знаешь ли ты, готов ли ты выслушать её маленькое, маленькое желание."
  },
  Event_129218_Name = {
    Text = "Сон чешуекрылого"
  },
  Event_129219_ChoiceDesc1 = {
    Text = "[Следовать указанию] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заражает «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129219_ChoiceDesc2 = {
    Text = "[Игнорировать указание] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заражает «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129219_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129219_Desc = {
    Text = "Празднество уже началось.\nПод пламенем духов и молитвами крови бесчисленные души верующих обратились в маяки —\nПризрачные духи рассеялись вокруг тебя, словно путеводные феи, мерцая светом в ожидании твоего выбора."
  },
  Event_129219_Name = {
    Text = "Маяк душ"
  },
  Event_129220_ChoiceDesc1 = {
    Text = "[Игнорировать звонок] Получить Улучш. гриф на выбор 1 из 3 дважды"
  },
  Event_129220_ChoiceDesc2 = {
    Text = "[Поднятие слуха]получает золотую реликвию「(RelicConfig.Arg1)», Погружение「(Skill.Arg2)」"
  },
  Event_129220_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_129220_Desc = {
    Text = "Она не должна была звенеть — тот телефон, свернувшийся за полотном. \n Провода трубки переплетены вокруг массивного корпуса, словно ржавая пуповина, кажется, тянущаяся из твоего мозга. \n Ты внимательно различаешь частоту вибрации, странный звук напоминает сюрреалистическое искусство Пикмана."
  },
  Event_129220_Name = {
    Text = "Пропущенный звонок"
  },
  Event_129221_ChoiceDesc1 = {
    Text = "[У нас всё хорошо] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129221_ChoiceDesc2 = {
    Text = "[Кто ты?] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129221_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129221_Desc = {
    Text = "Пишущая машинка резко выплюнула чернила, на ней было слишком много восклицательных знаков. \n\"Долл, ты в порядке??? Почему Страж исчез, а ты тоже исчезла!!! Пожалуйста, ответь, если все в порядке!!! Если это продолжится, Уильям останется без волос!!!\""
  },
  Event_129221_Name = {
    Text = "Экстренная связь"
  },
  Event_129222_ChoiceDesc1 = {
    Text = "\"Срезать красную ленту\" удалить 1 карту команды, получить Arg1 чёрную печать"
  },
  Event_129222_ChoiceDesc2 = {
    Text = "\"Противостояние\" копирует 1 Карту команды, заражает \"(Skill.Arg1)\""
  },
  Event_129222_ChoiceDesc3 = {
    Text = "[Призыв Рамоны] Выбрать 1 из 3 командных карт, получить гриф: [(EnchantConfig.Arg1)], повторить 2 раза"
  },
  Event_129222_Desc = {
    Text = "Касия бросила красную ленту, и в мгновение ока она обвилась вокруг твоего чемодана."
  },
  Event_129222_Name = {
    Text = "Переплетённый шёлк"
  },
  Event_129223_ChoiceDesc1 = {
