  },
  Event_129225_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129225_Name = {
    Text = "Забвение третья глава@"
  },
  Event_129226_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129226_Name = {
    Text = "Забвение глава 4@"
  },
  Event_129227_ChoiceDesc1 = {
    Text = "[Отогнать взмахом руки] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)» дважды, заражает «(Skill.Arg2)» дважды"
  },
  Event_129227_ChoiceDesc2 = {
    Text = "\"Разрешить пребывание\" получить Серебряная реликвия \"(RelicConfig.Arg1)\", инфицирование \"(Skill.Arg2)\""
  },
  Event_129227_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129227_Desc = {
    Text = "Из темноты донёсся тихий звук.\nЭто Глава о бабочке вежливо спрашивала.\n«Можно мне опуститься на твою ладонь?»\n«Я просто очень устала и хочу немного отдохнуть...»\nТак спрашивая, Глава о бабочке пролетела сквозь тьму и закружилась перед тобой.\nЧёрная слизь капала с её крыльев — дар тьмы, полученный бабочкой при пересечении мрака."
  },
  Event_129227_Name = {
    Text = "Просьба бабочки"
  },
  Event_129228_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129228_Name = {
    Text = "Забвение глава 7@"
  },
  Event_129229_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129229_Name = {
    Text = "Забвение глава 7@"
  },
  Event_129230_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129230_Name = {
    Text = "Забвение глава 1@"
  },
  Event_129231_ChoiceDesc1 = {
    Text = "\"распознать текст песни\"получить серебряное создание\"(RelicConfig.Arg1)\", Погружение\"(Skill.Arg2)\""
  },
  Event_129231_ChoiceDesc2 = {
    Text = "[Тихо напевать] Получить гриф на выбор из 3, повторить 2 раза"
  },
  Event_129231_Desc = {
    Text = "Древняя Песня лодочника звучит в мистическом мире. \n Память, застрявшая в мистическом мире, поёт на языке, который ты никогда не слышал, о волнах, небе и крепком алкоголе."
  },
  Event_129231_Name = {
    Text = "Морская баллада"
  },
  Event_129232_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129232_Name = {
    Text = "Забвение глава 8@"
  },
  Event_129233_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129233_Name = {
    Text = "Звёздное Царство 1@"
  },
  Event_129234_ChoiceDesc1 = {
    Text = "[Порезать ладонь] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)» дважды, заражает «(Skill.Arg2)» дважды"
  },
  Event_129234_ChoiceDesc2 = {
    Text = "[Принятие роста]получает серебряную реликвию「(RelicConfig.Arg1)», Погружение「(Skill.Arg2)」"
  },
  Event_129234_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129234_Desc = {
    Text = "Эта Глава о бабочке не прилетела, а медленно выросла из твоей ладони. \nСначала ты думал, что это просто пот, но между пальцами увидел черную жидкость, тихо просачивающуюся, как рефлюкс, конденсирующуюся в холодные и пульсирующие крылья. \nКаждое движение вызывает рябь в твоей крови."
  },
  Event_129234_Name = {
    Text = "Паразит"
  },
  Event_129235_ChoiceDesc1 = {
    Text = "[Продолжить листать] Случайная 1 Командная карта получает Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129235_ChoiceDesc2 = {
    Text = "\"Покинуть\" повышает максимальное здоровье на Arg1 единиц, наносит Эффект \"(Skill.Arg2)\""
  },
  Event_129235_Desc = {
    Text = "Весы для взвешивания. \n За ними безчисленные органы погружены в красный формалин. \n Они аккуратно сложены на полках. \n Ты поднимаешь лежащий рядом блокнот и просматриваешь: \n \"Сердце: 8 унций, мозг: 50 унций...\""
  },
  Event_129235_Name = {
    Text = "Регистрация органов"
  },
  Event_129236_ChoiceDesc1 = {
    Text = "\"Обходным путём\"удалить одну карту команды, получить Arg1 чёрную печать"
  },
  Event_129236_ChoiceDesc2 = {
    Text = "\"спросить причину затопления\" скопировать 1 карту команды, применить Эффект \"(Skill.Arg1)\""
  },
  Event_129236_ChoiceDesc3 = {
    Text = "[Поздороваться с членом экипажа] Выбрать 1 из 3 командных карт, получить гриф: [(EnchantConfig.Arg1)], повторить 2 раза"
  },
  Event_129236_Desc = {
    Text = "Идя по пути в машинное отделение, вы снова встретили несколько \"памятей\", застрявших в мистическом мире. \n Они не призраки, а лишь забота капитана Элтона о ушедших членах экипажа."
  },
  Event_129236_Name = {
    Text = "Владелец Сона-Нила"
  },
  Event_129237_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129237_Name = {
    Text = "Забвение третья глава@"
  },
  Event_129238_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129238_Name = {
    Text = "Звёздное Царство 1@"
  },
  Event_129239_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129239_Name = {
    Text = "Забвение глава 6@"
  },
  Event_129240_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129240_Name = {
    Text = "Забвение Глава 5@"
  },
  Event_129241_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129241_Name = {
    Text = "Звёздное Царство 4@"
  },
  Event_129242_ChoiceDesc1 = {
    Text = "[Сыграть для него] Выбрать 1 из 3 командных карт, получить гриф: «(EnchantConfig.Arg1)» дважды, заразить «(Skill.Arg2)» дважды"
  },
  Event_129242_ChoiceDesc2 = {
    Text = "\"Слушая звуки арфы\" за каждое пробуждающее тело с очагом ярости 50 и выше получите 15 чёрных печатей"
  },
  Event_129242_ChoiceDesc3 = {
    Text = "[Уйти] Получить гриф 3 на выбор дважды"
  },
  Event_129242_Desc = {
    Text = "\"Дорогой Джон: \n В последнее время я вдруг осознал, что с тех пор, как ты в последний раз играл для нас на пианино, прошло уже несколько лет. \n Мне 81 год, и с возрастом я все больше осознаю ценность воспоминаний о молодости. \n Если ты получишь это письмо, пожалуйста, в следующий раз, когда будешь проезжать мимо Лентиниена, остановись перед моей квартирой и сыграй для меня мелодию.\""
  },
  Event_129242_Name = {
    Text = "Соната сожаления"
  },
  Event_129243_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129243_Name = {
    Text = "Глава 3 звёзд@"
  },
  Event_129244_ChoiceDesc1 = {
    Text = "[Сказать, что нет кошелька] Получить Гриф на выбор из 3 дважды"
  },
  Event_129244_ChoiceDesc2 = {
    Text = "[Разорвать сеть] 1 случайная Командная карта получает Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129244_Desc = {
    Text = "Оранжево-желтая паутина тихо парит в воздухе, её дыры редки, и она далеко не так изящна, как дальний родственник, обитающий у корней стены. \n Ты не можешь удержаться и протягиваешь руку, хрупкая паутина мгновенно растворяется, и смех детей звучит у тебя за ухом. \n \"Золотые, серебряные, желтые, красные, все кошельки — наши!\""
  },
  Event_129244_Name = {
    Text = "Блуждающая сеть"
  },
  Event_129245_ChoiceDesc1 = {
    Text = "[Выбрать эмоциональный] восстанавливает Arg1 очков Жизни"
  },
  Event_129245_ChoiceDesc2 = {
    Text = "[Сохранять рассудок] Случайная 1 Командная карта получает Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129245_ChoiceDesc3 = {
    Text = "[Отказаться выбирать] получает 25 Черная печать"
  },
  Event_129245_Desc = {
    Text = "\"Выбирай, выбирай.\"\nВ безумно мчащейся тьме раздаются бесчисленные шёпоты.\nЭтот голос мягкий и гипнотический, кажется, наполнен бесконечной магией, вызывая у тебя некое безумное видение.\nТвой мозг погружается в безумие, извиваясь и покидая тело, а сердце, похоже, обрело некое сознание, взывая к тебе с криком.\n\"Выбирай, выбирай.\"\n\"Удержание разум или чувства, ты должен сделать выбор.\""
  },
  Event_129245_Name = {
    Text = "Плата человечности"
  },
  Event_129246_ChoiceDesc1 = {
    Text = "\"Уничтожить Жертва\"получить проклятое создание\"(RelicConfig.Arg1)\", инфицировать\"(Skill.Arg2)\""
  },
  Event_129246_ChoiceDesc2 = {
    Text = "[Развязать верёвку] Выбрать 1 из 3 командных карт, получить гриф: [(EnchantConfig.Arg1)], повторить 2 раза"
  },
  Event_129246_ChoiceDesc3 = {
    Text = "\"Продолжить вперёд\"получить 50 чёрных печатей"
  },
  Event_129246_Desc = {
    Text = "Трое арамеев были связаны на возвышении. \n На их телах появились темные коры, которые ты когда-то видел на детях, и они что-то бормочут."
  },
  Event_129246_Name = {
    Text = "Три жертвенных дара"
  },
  Event_129247_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129247_Name = {
    Text = "Глава 3 звёзд@"
  },
  Event_129248_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129248_Name = {
    Text = "Забвение глава 6@"
  },
  Event_129249_ChoiceDesc1 = {
    Text = "\"Стремление вперёд\"Удалить 1 карту команды, получить Arg1 чёрную печать"
  },
  Event_129249_ChoiceDesc2 = {
    Text = "\"Разрыв нить\"Скопируйте одну карту команды, Погружение\"(Skill.Arg1)\""
  },
  Event_129249_ChoiceDesc3 = {
    Text = "[Сдержаться] Выбрать 1 из 3 командных карт, получить гриф: [(EnchantConfig.Arg1)], повторить 2 раза"
  },
  Event_129249_Desc = {
    Text = "Тебя толкают вперёд на протяжении всего пути, и все твои выборы управляются невидимыми нитями. \n Ты стараешься двигать руками, пытаясь ухватить всё, что тебе важно. \n Судьба мира висит на кончиках твоих пальцев. \n Бесчисленные нити обвивают тебя, связывая всё твоё тело."
  },
  Event_129249_Name = {
    Text = "Руки куклы"
  },
  Event_129250_ChoiceDesc1 = {
    Text = "[Спросить у него дорогу] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129250_ChoiceDesc2 = {
    Text = "[Уйти от него] Выбери 1 из 3 Командных карт, чтобы получить Гриф: «(EnchantConfig.Arg1)», заражение «(Skill.Arg2)»"
  },
  Event_129250_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129250_Desc = {
    Text = "Тень стоит под тонким фонарём. \n \"Не могли бы вы одолжить Искра, сэр?\" \n У тебя нет привычки использовать @2, но ты не против немного \"магии\". \n С твоей помощью Чёрная Чёрная Чёрная Чёрная тень зажжёт @2 и погрузит его в невидимый чёрный Мальстрём. \n Через некоторое время ты увидишь, как белый дым начинает подниматься. \n \"Ах——\" \n Тень издаёт довольный вздох."
  },
  Event_129250_Name = {
    Text = "Силуэт под фонарём"
  },
  Event_129251_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129251_Name = {
    Text = "Забвение глава 1@"
  },
  Event_129252_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129252_Name = {
    Text = "Забвение глава 8@"
  },
  Event_129253_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129253_Name = {
    Text = "Забвение третья глава@"
  },
  Event_129254_ChoiceDesc1 = {
    Text = "[Принять Фантазм] Случайная 1 Командная карта получает Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129254_ChoiceDesc2 = {
    Text = "[Отрицать Фантазм] Выбрать 1 из 3 Командных карт и получить Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129254_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129254_Desc = {
    Text = "Под массивным тёмным железным мостом, на безмолвном речном побережье, заросшем камышами, вдруг выпорхнула сверкающая Глава о бабочке. \n Бабочка легко приземлилась на твою ладонь, гнетущий вой умолк, сменившись гулом поезда, проезжающего по ржавым стальным конструкциям, треском горящего угля, металлическим скрежетом вращающихся осей..."
  },
  Event_129254_Name = {
    Text = "Иллюзия железной дороги"
  },
  Event_129255_ChoiceDesc1 = {
    Text = "[Выбрать отказ] удаляет 1 карту приказа, получает Arg1 Черная печать"
  },
  Event_129255_ChoiceDesc2 = {
    Text = "[Выбрать подчинение]копирует 1 карту приказа, заражается「(Skill.Arg1)」"
  },
  Event_129255_ChoiceDesc3 = {
    Text = "[Выбрать объятие] Выбрать 1 из 3 Командных карт, которая получает Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129255_Desc = {
    Text = "\"Я — птица в клетке, запертая в дворе, полном множества комнат.\"\nВ темноте бродят неясные тени, это навязчивые идеи, оставленные ушедшими. \n\"Говорят, это Психиатрическая больница, но я знаю, что это особая клетка для людей, которые не хотят подчиняться социальным правилам — свободные птицы.\"\n\"Но если птица не может летать, можно ли её всё ещё называть птицей?\"\nНавязчивые идеи приближаются к тебе, умоляя о искуплении. \n\"Пожалуйста, сломай мои крылья, я устал от полёта.\""
  },
  Event_129255_Name = {
    Text = "Пустой человек"
  },
  Event_129256_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129256_Name = {
    Text = "Забвение Глава 2@"
  },
  Event_129257_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129257_Name = {
    Text = "Глава 2 Звёзд@"
  },
  Event_129258_ChoiceDesc1 = {
    Text = "[Освободить бабочку] Выбрать 1 из 3 командных карт, получить гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заразить «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129258_ChoiceDesc2 = {
    Text = "\"Стать бабочкой\" получает серебряное создание \"(RelicConfig.Arg1)\", применяет Эффект \"(Skill.Arg2)\""
  },
  Event_129258_ChoiceDesc3 = {
    Text = "\"Глотание обратно в живот\"25 чёрных печатей получено"
  },
  Event_129258_Desc = {
    Text = "Этой ночью произошло слишком много событий. \n АТК на причал, призрачный грузовой корабль, Плаватель морей, Тулу, Мёрфи, Рамона... Всё это вертится в вихре, перемешиваясь в овсянку, подаваемую в ресторане Мисаг в Часть 7 утра. \n Я хотел задать вопрос перед пробуждённым, но не знал, как его задать, словно что-то застряло в горле — или, можно сказать, бабочки в животе."
  },
  Event_129258_Name = {
    Text = "Эффект бабочки"
  },
  Event_129259_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129259_Name = {
    Text = "Забвение глава 8@"
  },
  Event_129260_ChoiceDesc1 = {
    Text = "[Позволить остаться] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129260_ChoiceDesc2 = {
    Text = "\"махать рукой, чтобы прогнать\"получить серебряное создание \"(RelicConfig.Arg1)\", Погружение \"(Skill.Arg2)\""
  },
  Event_129260_ChoiceDesc3 = {
    Text = "\"Встреча с бабочкой\" получить 25 чёрных печатей"
  },
  Event_129260_Desc = {
    Text = "Вы бродите по санаторию, где свирепствует холодный ветер, и вдруг к вам приближается черная Глава о бабочке, которая не должна существовать в это время года. \n На крыльях бабочки тянется черная слизь, она качаясь пролетает мимо, слои черной жидкости, вытекающей из крыльев, после застывания сдуваются ветром. \n Она устала лететь и приземлилась на кончик твоего пальца."
  },
  Event_129260_Name = {
    Text = "Что не должно существовать"
  },
  Event_129261_ChoiceDesc1 = {
    Text = "[Вспомнить прошлое] Дважды получить улучш. гриф на выбор из трёх"
  },
  Event_129261_ChoiceDesc2 = {
    Text = "[Заглянуть в будущее]получено Золотая реликвия \"(RelicConfig.Arg1)\", Погружение \"(Skill.Arg2)\""
  },
  Event_129261_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_129261_Desc = {
    Text = "Ничто в мире не может оставаться неизменным.\nДаже рай, созданный Богиней-Матерью, не исключение.\nВ краткий миг ты увидел нечто сквозь пространственно-временной разлом.\nПрошлое, настоящее, будущее переплетаются в этой испещрённой трещинами расщелине, непрестанно меняясь.\nОжидая твоего любопытного взгляда."
  },
  Event_129261_Name = {
    Text = "Пространственно-временной разлом"
  },
  Event_129262_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129262_Name = {
    Text = "Забвение глава 7@"
  },
  Event_129263_ChoiceDesc1 = {
    Text = "[Игнорировать это] Получить Гриф на выбор 1 из 3 дважды"
  },
  Event_129263_ChoiceDesc2 = {
    Text = "[Прикоснуться к этому] Случайная 1 Командная карта получает Гриф: «(EnchantConfig.Arg1)» дважды, заражает «(Skill.Arg2)» дважды"
  },
  Event_129263_Desc = {
    Text = "Странный объект, похожий на споры, привлёк твоё внимание. \n Он напоминает тонкого медузу, состоящую из мяса и крови, а также нервные волокна, хранящие сигналы в глубинах мозга. \n \"Прикоснись ко мне.\" Он безмолвно искушает тебя, \"Я покажу тебе жестокую память.\""
  },
  Event_129263_Name = {
    Text = "Глубокая память"
  },
  Event_129264_ChoiceDesc1 = {
    Text = "[Погрузиться в фантазии] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)» дважды, заражает «(Skill.Arg2)» дважды"
  },
  Event_129264_ChoiceDesc2 = {
    Text = "[Удержание рассудок] За каждого пробуждённого с уровнем безумия 50 и выше получить 15 чёрных печатей"
  },
  Event_129264_ChoiceDesc3 = {
    Text = "[Уйти силой] Получить Гриф на выбор 1 из 3, повторить 2 раза"
  },
  Event_129264_Desc = {
    Text = "Возможно, долгие сражения вызвали у тебя помутнение, а может, твой мозг просто предал твоё тело.\nНекое чувство невесомости возникло в твоём сознании.\nВ одно мгновение твой разум превратился в калейдоскоп — яркий, пёстрый, мерцающий всеми цветами радуги.\nБесчисленные вдохновения, наваждения и безумные фантазии хлынули в мозг, заполняя каждый уголок его извилин.\nЕсли так продолжится, твою голову скоро разорвёт от всего этого хаоса."
  },
  Event_129264_Name = {
    Text = "Калейдоскоп разума"
  },
  Event_129265_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129265_Name = {
    Text = "Забвение Глава 5@"
  },
  Event_129266_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129266_Name = {
    Text = "Забвение глава 4@"
  },
  Event_129267_ChoiceDesc1 = {
    Text = "[Слушать] Получить улучш. гриф на выбор из 3, повторить 2 раза"
  },
  Event_129267_ChoiceDesc2 = {
    Text = "\"Крик\" получил Золотая реликвия \"(RelicConfig.Arg1)\", заражён \"(Skill.Arg2)\""
  },
  Event_129267_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_129267_Desc = {
    Text = "С тех пор как произошёл инцидент, ты больше не получал новостей от партнёра. \n Бесчисленные попытки связи были сделаны, но они были как камень, упавший в море, без эха. \n В тот момент, когда ты уже не надеялся, устройство связи вдруг издало звук. \n Ты открыл чемодан и поднёс трубку к уху. \n \"Страж...\" \n В замешательстве ты услышал тот голос, который всегда так сильно скучал, как будто он доносился из далека, из-за слоя пустоты."
  },
  Event_129267_Name = {
    Text = "Эхо тоски"
  },
  Event_129268_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129268_Name = {
    Text = "Забвение глава 1@"
  },
  Event_129269_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129269_Name = {
    Text = "Звёздное Царство 1@"
  },
  Event_129270_ChoiceDesc1 = {
    Text = "\"Прямое Наблюдение за адским псом Генезис\"получить Золотая реликвия\"(RelicConfig.Arg1)\", заражено\"(Skill.Arg2)\""
  },
  Event_129270_ChoiceDesc2 = {
    Text = "[Сосредоточиться на бою] Выбрать 1 из 3 Командных карт и получить Гриф: [(EnchantConfig.Arg1)], повторить 2 раза"
  },
  Event_129270_Desc = {
    Text = "Контур адского пса меняется.\nЕго тело соединяется с трещинами в стене, создавая красивую и загадочную иллюзию."
  },
  Event_129270_Name = {
    Text = "От перспективы"
  },
  Event_129271_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129271_Name = {
    Text = "Забвение Глава 2@"
  },
  Event_129272_ChoiceDesc1 = {
    Text = "\"Соединение бумаги\" получает золотое создание \"(RelicConfig.Arg1)\", инфицировано \"(Skill.Arg2)\""
  },
  Event_129272_ChoiceDesc2 = {
    Text = "[Прочитать] Выбрать 1 из 3 Командных карт и получить Гриф: [(EnchantConfig.Arg1)] дважды"
  },
  Event_129272_ChoiceDesc3 = {
    Text = "\"Бросить его\" получить 50 чёрных печатей"
  },
  Event_129272_Desc = {
    Text = "С пожелтевшей страницы, выпавшей из-под рясы сектантов с фонарями, густо написаны странные тексты, некоторые из которых напоминают иероглифы, некоторые странно поднимаются вверх, а некоторые буквы даже накладываются Близкий Близкий Близкий Близкий друг на друга, лишь небольшое количество слов можно с трудом разобрать. \nЗаголовок: «@2 Рождение Святого Сына»"
  },
  Event_129272_Name = {
    Text = "Приказ·Вниз"
  },
  Event_129273_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129273_Name = {
    Text = "Забвение Глава 2@"
  },
  Event_129274_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129274_Name = {
    Text = "Глава 2 Звёзд@"
  },
  Event_129275_ChoiceDesc1 = {
    Text = "[Приготовиться к бою] Выбрать 1 из 3 Командных карт, которая получает Гриф: «(EnchantConfig.Arg1)», повторить 2 раза, заражает «(Skill.Arg2)», повторить 2 раза"
  },
  Event_129275_ChoiceDesc2 = {
    Text = "[Попытаться обойти] получить 25 чёрных печатей"
  },
  Event_129275_Desc = {
    Text = "В глубинах моря, куда ниспадает звёздный Погоня за светом, ступающие по морю затаились на тысячи лет.\nБескрайние воды были свидетелями их безумия, их терпения, а также их самой истовой веры в божество.\nНикто не в силах помешать великому пришествию божества.\nВсякий, кто встанет на пути, обратится в Пепел в гневе ступающих по морю."
  },
  Event_129275_Name = {
    Text = "Ожидание под звёздами"
  },
  Event_129276_ChoiceDesc1 = {
    Text = "Игрок получает Серебряная реликвия \"(RelicConfig.Arg1)\", подвергается заражению \"(Skill.Arg2)\""
  },
  Event_129276_ChoiceDesc2 = {
    Text = "[Закрыть крышку] Получить Гриф на выбор из 3 дважды"
  },
  Event_129276_Desc = {
    Text = "Пианино у стены открыто. У него пожелтевшие клавиши и треснувшие края, обнажающие древесину, но каждая клавиша тщательно вытерта. \n Оно является источником радости для многих людей."
  },
  Event_129276_Name = {
    Text = "Мелодия детства"
  },
  Event_129277_ChoiceDesc1 = {
    Text = "[Принять Фантазм] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129277_ChoiceDesc2 = {
    Text = "\"отрицание иллюзии\"получить создание из серебра \"(RelicConfig.Arg1)\", влияние \"(Skill.Arg2)\""
  },
  Event_129277_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_129277_Desc = {
    Text = "Под массивным тёмным железным мостом, на безмолвном речном побережье, заросшем камышами, вдруг выпорхнула сверкающая Глава о бабочке.\nБабочка легко приземлилась на твою ладонь, гнетущий вой умолк, сменившись размеренным криком рабочих, переносящих стальные балки, стуком молотков и звонким звуком сталкивающихся заклёпок..."
  },
  Event_129277_Name = {
    Text = "Иллюзия стального моста"
  },
  Event_129278_ChoiceDesc1 = {
    Text = "[Показать Проклятие] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)» дважды, заразиться «(Skill.Arg2)» дважды"
  },
  Event_129278_ChoiceDesc2 = {
    Text = "[Отвергнуть ворона] Получить Гриф на выбор из 3, повторить 2 раза"
  },
  Event_129278_ChoiceDesc3 = {
    Text = "\"игнорировать\""
  },
  Event_129278_Desc = {
    Text = "Чёрная и болезненная многоголовая ворона вылетела из чёрной мантии сектанта с фонарём и приземлилась на твоём плече. \n \"Видишь мою голову? Как только я попробую проклятие, у меня вырастет новая голова. Давай посмотрим, какое у тебя проклятие!\""
  },
  Event_129278_Name = {
    Text = "Проклятая ворона"
  },
  Event_129279_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129279_Name = {
    Text = "Забвение глава 7@"
  },
  Event_129280_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129280_Name = {
    Text = "Забвение третья глава@"
  },
  Event_129281_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129281_Name = {
    Text = "Забвение глава 4@"
  },
  Event_129282_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129282_Name = {
    Text = "Забвение Глава 2@"
  },
  Event_129283_ChoiceDesc1 = {
    Text = "[Заполнение] временный текст."
  },
  Event_129283_Name = {
    Text = "Глава 2 Звёзд@"
  },
  Event_129900_ChoiceDesc1 = {
    Text = "\"Погребение\"Лечение Arg2 очков жизни[ExDesc1], выбор 1 Карты команды удалить."
  },
  Event_129900_ChoiceDesc2 = {
    Text = "[Текст молитвы]получить Золотая реликвия «(RelicConfig.Arg1)», Погружение «(Skill.Arg2)»"
  },
  Event_129900_Desc = {
    Text = "Обломок бледной кости, частично погруженный в черную лаву растворения."
  },
  Event_129900_Name = {
    Text = "Выцветшие останки"
  },
  Event_130337_ChoiceDesc1 = {
    Text = "[Занять место]Поместить «Марионетку» в колоду."
  },
  Event_130337_Desc = {
    Text = "Стоило твоим ногам ступить на ступени театра, как взгляд уже не в силах оторваться от этой сцены.\nНити судьбы влекут бесчисленные истории, что кружатся здесь — прах минувшего, тени настоящего, туман грядущего — всё клубится перед рампой, не зная покоя.\nТы забыл, откуда пришёл и куда стремился; всё, что составляло твоё «я», растворилось в тени занавеса. В этот миг ты — безмолвный зритель в зале и пылающий актёр на подмостках.\nВесь смысл твоего существования схлопнулся в два следа: созерцать и играть."
  },
  Event_130337_Name = {
    Text = "Сцена судьбы"
  },
  Event_131264_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_131264_Desc = {
    Text = "Вы выбрали силу, выбрали непоколебимую веру и безудержную отвагу.\nНо… цена… Смысл существования цены в том, чтобы её принять, не так ли?"
  },
  Event_131264_Name = {
    Text = "Взгляд из прошлого"
  },
  Event_131265_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_131265_Desc = {
    Text = "Ты терпишь боль, пронизывающую разум, и крепко сжимаешь рассеивающиеся, разбитые воспоминания. Благодаря твоей мучительной стойкости трещины начинают затягиваться.\nТы ушёл, чтобы помнить, и сражаешься, чтобы помнить. Ты не позволишь ни одному воспоминанию покинуть тебя."
  },
  Event_131265_Name = {
    Text = "Разбитые воспоминания"
  },
  Event_131266_ChoiceDesc1 = {
    Text = "[Защитить воспоминания] Получить Очарование(выбор 1 из 3)"
  },
  Event_131266_ChoiceDesc2 = {
    Text = "[Остановить разлом]Выберите 1 из 3 командных карт, чтобы получить Очарование: «(EnchantConfig.Arg1)», Погружение «(Skill.Arg2)»"
  },
  Event_131266_Desc = {
    Text = "Ты никогда не сомневался в своих воспоминаниях. Они были тёплыми, прочными — твоей самой надёжной гаванью и самым драгоценным сокровищем.\nНо теперь, под воздействием Бездны, в тех воспоминаниях начали появляться хаотичные трещины."
  },
  Event_131266_Name = {
    Text = "Разбитые воспоминания"
  },
  Event_131267_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_131267_Desc = {
    Text = "Духовная Огромная Огромная сила хлынула в разум, залатывая ужасающие трещины. Ты приложил все усилия и наконец восстановил целостность разломов.\nТы ушёл, чтобы помнить, и сражаешься, чтобы помнить. Ты не позволишь ни одному воспоминанию покинуть тебя."
  },
  Event_131267_Name = {
    Text = "Разбитые воспоминания"
  },
  Event_131268_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_131268_Desc = {
    Text = "«У-у-у-у… Ха-ха-ха-ха!!»\nНикто не понял твоих расспросов — они ответили рыданиями и пронзительным хохотом."
  },
  Event_131268_Name = {
    Text = "Покинутые"
  },
  Event_131269_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_131269_Desc = {
    Text = "Вы обращаете к ним ответный взгляд. Нити приходят в движение, нежный взор заключает воспоминания в объятия.\nТы молча смотришь на ту, кто управляет судьбой. Если бы всё можно было начать сначала, какой выбор она бы сделала?"
  },
  Event_131269_Name = {
    Text = "Взгляд из прошлого"
  },
  Event_131270_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_131270_Desc = {
    Text = "«У-у-у-у… Ха-ха-ха-ха!!»\nРыдания и пронзительный хохот постепенно рассеялись перед тобой. Ни одна душа не причинила тебе вреда — они давно привыкли быть незамеченными."
  },
  Event_131270_Name = {
    Text = "Покинутые"
  },
  Event_131271_ChoiceDesc1 = {
    Text = "[Вглядеться в воспоминания]Получить Золотая реликвия «(RelicConfig.Arg1)», Погружение «(Skill.Arg2)»"
  },
  Event_131271_ChoiceDesc2 = {
    Text = "[Забыть воспоминания]Случайно пробудить 2 пробуждённых, Погружение дважды «(Skill.Arg1)»"
  },
  Event_131271_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 50 чёрные Печать пакиа"
  },
  Event_131271_Desc = {
    Text = "Внутри тела девочки ты слышишь звук разбивающихся сосудов. Воспоминания покидают свои вместилища и приходят к вам.\nДетские товарищи по играм, подарки родителей, чистейшие фантазии о белых облаках и птицах, идеалы, белоснежные как небо… Все воспоминания открывают глаза и тихо смотрят на вас.\nОни вопрошают. Они плачут. Они ждут."
  },
  Event_131271_Name = {
    Text = "Взгляд из прошлого"
  },
  Event_131272_ChoiceDesc1 = {
    Text = "[Спросить] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)», заразить «(Skill.Arg2)»"
  },
  Event_131272_ChoiceDesc2 = {
    Text = "[Игнорировать] Выбрать 1 из 3 Командных карт и получить Гриф: «(EnchantConfig.Arg1)», заразить «(Skill.Arg2)»"
  },
  Event_131272_ChoiceDesc3 = {
    Text = "\"Покинуть\" получить 25 чёрных печатей"
  },
  Event_131272_Desc = {
    Text = "Пронзительные вопли раздаются у тебя в ушах, страдающие души рвут свои лица и тела прямо перед тобой…\nКто они? Узники Бездны? Отвергнутые судьбой? Погребённые воспоминания?"
  },
  Event_131272_Name = {
    Text = "Покинутые"
  },
  Event_133380_ChoiceDesc1 = {
    Text = "\"Подтвердить\""
  },
  Event_133380_Desc = {
    Text = "Ты опустился в предназначенное тебе бархатное кресло, и алый Занавес опускается бесшумно раздвинулся.\nДорогой зритель, сцена ответит на твои ожидания.\nИсполнитель главной роли этой пьесы уже вышел на сцену."
  },
  Event_133380_Name = {
    Text = "Сцена судьбы"
  },
  Event_141995_ChoiceDesc1 = {
    Text = "[Простая попытка] Удалить до 5 произвольных Карт"
  },
  Event_141995_ChoiceDesc2 = {
    Text = "[Предоставить ему исследование] Случайно удалить 5 Командных карт, получить Благословенную реликвию [(RelicConfig.Arg1)]."
  },
  Event_141995_ChoiceDesc3 = {
    Text = "[Обратное мышление?] Выбрать до двух Пробуждённых, создать полный набор их базовых Карт и поместить в колоду"
  },
  Event_141995_Desc = {
    Text = "Ты вышел на площадь, где множество людей куда-то спешат — быть может, здесь найдётся что-нибудь интересное.\nТы постучал в дверь комнаты с тусклым жёлтым светом, и оттуда выглянул человек в облике исследователя. Ты заметил множество незнакомых научных приборов; он усадил тебя и представился «эволюционистом». С лицом, пылающим Безумием, он настойчиво расхваливал тебе свой «научный метод».\n«Лишь удалив скучные излишки человеческой природы, можно встать на истинный Путь эволюции!»"
  },
  Event_141995_Name = {
    Text = "Эволюционист"
  },
  Event_141996_ChoiceDesc1 = {
    Text = "[Тренировка на атаку] Добавить случайный Гриф ко всем Базовым ударам без Грифа"
  },
  Event_141996_ChoiceDesc2 = {
    Text = "[Тренировка на защиту] Добавить случайный Гриф ко всем Базовым защитам без Грифа"
  },
  Event_141996_ChoiceDesc3 = {
    Text = "[Тренироваться не щадя себя] Добавить случайный Гриф к случайным 15 Командным картам, получить 5 случайных Карт симптома"
  },
  Event_141996_Desc = {
    Text = "Ты приходишь на площадь, где снуют люди в спешке. Возможно, здесь можно найти что-нибудь интересное.\nЗвонкий лязг металла разносится по открытому пространству: несколько человек упражняются здесь, оттачивая боевое мастерство. Молодой человек в старинных доспехах замечает тебя и бросает тебе меч, приглашая тренироваться вместе с ними."
  },
  Event_141996_Name = {
    Text = "Время усиленных тренировок"
  },
  Event_141997_ChoiceDesc1 = {
    Text = "[Ставка на большое] 50% шанс получить случайный гриф и сделать ставку снова, 50% шанс получить 75 чёрных печатей"
  },
  Event_141997_ChoiceDesc2 = {
    Text = "[Ставка на малое] 50% шанс получить случайный гриф и сделать ставку снова, 50% шанс получить 75 чёрных печатей"
  },
  Event_141997_Desc = {
    Text = "Официант, не меняя улыбки, поднимает стакан для кубиков — раздаётся звонкий звук, и остальные игроки делают свой выбор. «Ставки сделаны», — говорит он. — «Делайте ставки—»"
  },
  Event_141997_Name = {
    Text = "Шумное казино"
  },
  Event_141998_ChoiceDesc1 = {
    Text = "[Честная ставка] Удалить одну командную карту"
  },
  Event_141998_ChoiceDesc2 = {
    Text = "[Попробовать смошенничать] Удалить одну карту симптома"
  },
  Event_141998_ChoiceDesc3 = {
    Text = "\"покинуть\""
  },
  Event_141998_Desc = {
    Text = "Ты оказываешься в невероятно оживлённом месте: на лицах у всех сияет счастье, а разноцветные огни мигают так ярко, что ночи просто некуда деться. Повсюду развешаны таблички с надписью: «Добро пожаловать на карнавал! Здесь сны не знают конца, здесь радость не знает завершения!»\nТолпа подхватывает тебя и вносит в роскошное здание. Зал сверкает золотом, гул голосов не смолкает, а в воздухе разлит сладкий аромат вина. Кубик, громко стуча, подкатывается прямо к твоим ногам, и официант с льстивой улыбкой говорит, что это знак удачи. Движимый любопытством, ты делаешь шаг вперёд — быть может, в этой игре тебе удастся блеснуть."
  },
  Event_141998_Name = {
    Text = "Шумное казино"
  },
  Event_141999_ChoiceDesc1 = {
    Text = "[Бартер] Убрать 1 реликвию, с вероятностью 50% получить 1 из 3 золотых реликвий, с вероятностью 50% получить 25 чёрных печатей"
  },
  Event_141999_ChoiceDesc2 = {
    Text = "\"покинуть\""
  },
  Event_141999_Desc = {
    Text = "Ты оказываешься в невероятно оживлённом месте, где на лицах у всех сияет счастье, а разноцветные огни мерцают так ярко, что не оставляют ночи ни единого уголка. Повсюду видны таблички с надписью: «Добро пожаловать на карнавал! Здесь сны не знают конца, здесь радость не знает завершения!»\nИз толпы тебе машет торговец в лохмотьях, несущий огромный тюк. Он похлопывает по нему рукой, наклоняется и вполголоса предлагает тебе бартер. Его потрёпанная котомка тихонько покачивается в такт его словам и время от времени издаёт скрипучие звуки."
  },
  Event_141999_Name = {
    Text = "Оборванный странствующий торговец"
  },
  Event_142000_ChoiceDesc1 = {
    Text = "[Попробовать загадать желание] Потратить 50% текущих ОЗ, получить 2 случайные Золотые реликвии"
  },
  Event_142000_ChoiceDesc2 = {
    Text = "[Загадать желание всей душой] Потратить 99% текущих ОЗ, получить Хрономаятник [(RelicConfig.Arg2)]"
  },
  Event_142000_ChoiceDesc3 = {
    Text = "[Опустить руку на дно бассейна] Получить Золотую реликвию [(RelicConfig.Arg1)]"
  },
  Event_142000_Desc = {
    Text = "Ветер гуляет по полям, вокруг царит тишина, нарушаемая лишь шелестом деревьев.\nВнезапно ты слышишь журчание чего-то текущего. Идя на звук, ты сначала чувствуешь густой сладковато-железистый запах, и наконец видишь источник этого журчания — это бассейн желаний, наполненный алым: кровь бесчисленных людей пульсирует в нём, словно под поверхностью жидкости вот-вот что-то вырвется наружу.\nГолос раздаётся прямо в глубине твоего сердца: «Принеси свою кровь, и я одарю тебя милостью.»"
  },
  Event_142000_Name = {
    Text = "Кровавый источник"
  },
  Event_142001_ChoiceDesc1 = {
    Text = "[Простое подношение] Выбрать и удалить 2 реликвии, получить грешную реликвию [(RelicConfig.Arg1)]"
  },
  Event_142001_ChoiceDesc2 = {
    Text = "[Преданное подношение] Выбрать и удалить 4 реликвии, получить благословенную реликвию [(RelicConfig.Arg1)]"
  },
  Event_142001_ChoiceDesc3 = {
    Text = "[Стащить немного подношений — никто не узнает] Получить золотую реликвию [(RelicConfig.Arg1)]"
  },
  Event_142001_Desc = {
    Text = "Ветер гуляет по полям, вокруг царит тишина, нарушаемая лишь шелестом деревьев.\nНезаметно для себя ты оказываешься перед древним алтарём. Огромная статуя взирает на тебя сверху вниз, словно желая забрать что-то из твоих рук. Ты замечаешь размытую надпись у самого основания алтаря — «Равновесие обретения и утраты»."
  },
  Event_142001_Name = {
    Text = "Алтарь обретения и утраты"
  },
  Event_142002_ChoiceDesc1 = {
    Text = "[Бесплатная услуга] Случайное улучшение Arg2 Серебряных реликвий"
  },
  Event_142002_ChoiceDesc2 = {
    Text = "[Обычная услуга] Потратить Arg1 Чёрных печатей: случайное улучшение Arg2 Серебряных реликвий"
  },
  Event_142002_ChoiceDesc3 = {
    Text = "[Премиум-услуга] Потратить Arg1 Чёрных печатей: случайное улучшение Arg2 Серебряных реликвий"
  },
  Event_142002_Desc = {
    Text = "Ты вышел на площадь, где множество людей куда-то спешат — быть может, здесь найдётся что-нибудь интересное.\nНебольшое здание с тёплым освещением тихо стоит в углу площади — похоже на элитный клуб, однако на стене висит тёмная табличка с надписью: «Наше заведение обслуживает исключительно существ нечеловеческой природы.»"
  },
  Event_142002_Name = {
    Text = "Особый клуб"
  },
  Event_142003_ChoiceDesc1 = {
    Text = "[Попытать удачу] Получить одну карту симптома"
  },
  Event_142003_ChoiceDesc2 = {
    Text = "[Уйти] Получить 75 чёрных печатей"
  },
  Event_142003_Desc = {
    Text = "Ты оказываешься в невероятно оживлённом месте: на лицах у всех сияет счастье, а разноцветные огни мигают так ярко, что ночи просто некуда деться. Повсюду развешаны таблички с надписью: «Добро пожаловать на карнавал! Здесь сны не знают Конца, здесь Радость не знает Завершения!»\nТы замечаешь у дороги лотерейный лоток, окружённый людьми — все люди устремили Взгляды на главный приз, тщательно скрытый от посторонних глаз. Продавец вовсю расхваливает его редкость, и люди наперебой стремятся принять участие."
  },
  Event_142003_Name = {
    Text = "Лотерейное испытание"
  },
  Event_142004_ChoiceDesc1 = {
    Text = "[Воспользоваться]"
  },
  Event_142004_ChoiceDesc2 = {
    Text = "\"покинуть\""
  },
  Event_142004_Desc = {
    Text = "Ветер гуляет по полям, вокруг царит тишина, нарушаемая лишь шелестом деревьев.\nВнезапно ты замечаешь ветхий соломенный навес: в самом его центре стоит наковальня, а рядом валяется немало заржавевшего металлического оружия. Похоже, это давно заброшенная кузница. Рядом с наковальней лежит подробная инструкция по использованию, из которой следует, что здесь можно переделывать реликвии."
  },
  Event_142004_Name = {
    Text = "Кузница"
  },
  Event_142005_ChoiceDesc1 = {
    Text = "[Честная ставка] Удалить одну командную карту"
  },
  Event_142005_ChoiceDesc2 = {
    Text = "[Попробовать смошенничать] Удалить одну карту симптома"
  },
  Event_142005_ChoiceDesc3 = {
    Text = "\"покинуть\""
  },
  Event_142005_Desc = {
    Text = "Возгласы окружающих возвещают о твоей победе. В шуме голосов ты наконец становишься одним из них — опьянённым этим причудливым сном, в котором поставлено всё. Ты смотришь на фишки в своих руках, словно они — твои самые верные друзья, принёсшие тебе славу, а из глубины игорного стола доносится шёпот, несущий в себе двусмысленную просьбу: «Повторная попытка, выиграй ещё раз»."
  },
  Event_142005_Name = {
    Text = "Шумное казино"
  },
  Event_142013_ChoiceDesc1 = {
    Text = "[Ставка на большое] 50% шанс получить случайную серебряную реликвию и сделать ставку снова, 50% шанс получить 75 чёрных печатей и вступить в бой с элитой"
  },
  Event_142013_ChoiceDesc2 = {
    Text = "[Ставка на малое] 50% шанс получить случайную серебряную реликвию и сделать ставку снова, 50% шанс получить 75 чёрных печатей и вступить в бой с элитой"
  },
  Event_142013_Desc = {
    Text = "Официант, не меняя улыбки, поднимает стакан для кубиков — раздаётся звонкий звук, и остальные игроки делают свой выбор. «Ставки сделаны», — говорит он. — «Делайте ставки—»"
  },
  Event_142013_Name = {
    Text = "Шумное казино"
  },
  Event_142073_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_142073_Desc = {
    Text = "Официант поднимает стакан для кубиков — и на несколько мгновений воздух словно застывает в стагнации. В миг, когда ответ открывается, ты слышишь, как крики радости смешиваются с воплями отчаяния. Удача не улыбнулась тебе: кубики, спокойно лежащие на столе, показали результат, противоположный твоей ставке. Ты напоследок обводишь взглядом зал, смотришь на этих безумных игроков. Пора уходить."
  },
  Event_142073_Name = {
    Text = "Шумное казино"
  },
  Event_142074_ChoiceDesc1 = {
    Text = "[Начало битвы]"
  },
  Event_142074_Desc = {
    Text = "Пока ты с нетерпением впиваешься взглядом в игорный стол, твою руку вдруг крепко хватают. Подняв голову, ты видишь босса казино, который нависает над тобой, готовясь выпроводить всех нарушителей правил. В тот же миг все взгляды устремляются на тебя — изумлённые, враждебные, злорадные... Ты понимаешь: человек может мошенничать много раз, но пока его поймают хотя бы однажды — полный позор и крах неизбежны."
  },
  Event_142074_Name = {
    Text = "Шумное казино"
  },
  Event_142103_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_142103_Desc = {
    Text = "Тебе удаётся вырваться из казино физическим путём. Шум толпы остаётся позади, ты ускоряешь шаг и уходишь — а весь этот беспорядок кто-нибудь да уберёт."
  },
  Event_142103_Name = {
    Text = "Шумное казино"
  },
  Event_142105_ChoiceDesc1 = {
    Text = "[Ещё раз] Получить карту симптома"
  },
  Event_142105_ChoiceDesc2 = {
    Text = "[Уйти] Получить 75 чёрных печатей"
  },
  Event_142105_Desc = {
    Text = "Ты пробуешь разок — ничего не происходит. Но на обороте карточки написано: «В следующий раз будет легче»\n......Попробовать ещё раз?"
  },
  Event_142105_Name = {
    Text = "Лотерейное испытание"
  },
  Event_142106_ChoiceDesc1 = {
    Text = "[Ещё раз] Получить карту симптома"
  },
  Event_142106_ChoiceDesc2 = {
    Text = "[Уйти] Получить 75 чёрных печатей"
  },
  Event_142106_Desc = {
    Text = "Ты пробуешь разок — ничего не происходит. Но на обороте карточки написано: «В следующий раз будет легче»\n......Попробовать ещё раз?"
  },
  Event_142106_Name = {
    Text = "Лотерейное испытание"
  },
  Event_142107_ChoiceDesc1 = {
    Text = "[Ещё раз] Получить карту симптома"
  },
  Event_142107_Desc = {
    Text = "Ты пробуешь разок — ничего не происходит. Но на обороте карточки написано: «В следующий раз будет легче»\n......Попробовать ещё раз?"
  },
  Event_142107_Name = {
    Text = "Лотерейное испытание"
  },
  Event_142108_ChoiceDesc1 = {
    Text = "[Ещё раз] Получить карту симптома"
  },
  Event_142108_ChoiceDesc2 = {
    Text = "[Уйти] Получить 75 чёрных печатей"
  },
  Event_142108_Desc = {
    Text = "Ты пробуешь разок — ничего не происходит. Но на обороте карточки написано: «В следующий раз будет легче»\n......Попробовать ещё раз?"
  },
  Event_142108_Name = {
    Text = "Лотерейное испытание"
  },
  Event_142109_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_142109_Desc = {
    Text = "Прислушиваясь к биению сердца, ты открываешь лотерейный билет, и ослепительно золотые буквы бросаются тебе в глаза. Продавец возбуждённо звонит в колокольчик, и все прохожие смотрят на тебя с завистью.\n«Главный приз уже выигран!»"
  },
  Event_142109_Name = {
    Text = "Лотерейное испытание"
  },
  Event_142110_ChoiceDesc1 = {
    Text = "[Ещё раз] Получить карту симптома"
  },
  Event_142110_ChoiceDesc2 = {
    Text = "[Уйти] Получить 75 чёрных печатей"
  },
  Event_142110_Desc = {
    Text = "Ты пробуешь разок — ничего не происходит. Но на обороте карточки написано: «В следующий раз будет легче»\n......Попробовать ещё раз?"
  },
  Event_142110_Name = {
    Text = "Лотерейное испытание"
  },
  Event_142118_ChoiceDesc1 = {
    Text = "[Бартер] Убрать 1 реликвию, с вероятностью 25% получить 1 из 3 хрономаятников, с вероятностью 50% получить 2 случайные золотые реликвии, с вероятностью 25% получить 25 чёрных печатей"
  },
  Event_142118_ChoiceDesc2 = {
    Text = "\"покинуть\""
  },
  Event_142118_Desc = {
    Text = "Торговец берёт переданный тобой предмет и долго вертит его на лунном свете, едва не выпучив глаза. Ты ждёшь долго, прежде чем он наконец ухмыляется и достаёт из тюка ржавую железную коробку. «Давай откроем — это самый модный нынче слепой бокс.»\nТы открываешь её, но обнаруживаешь внутри лишь несколько разочаровывающих чёрных печатей. Торговец потирает руки и с виноватым видом предлагает попробовать ещё раз."
  },
  Event_142118_Name = {
    Text = "Оборванный странствующий торговец"
  },
  Event_142119_ChoiceDesc1 = {
    Text = "\"покинуть\""
  },
  Event_142119_Desc = {
    Text = "Торговец берёт переданный тобой предмет и долго вертит его на лунном свете, едва не выпучив глаза. Ты ждёшь долго, прежде чем он наконец ухмыляется и достаёт из тюка ржавую железную коробку. «Давай откроем — это самый модный нынче слепой бокс.»\nТы открываешь её, и внутри лежит нечто."
  },
  Event_142119_Name = {
    Text = "Оборванный странствующий торговец"
  },
  Event_142120_ChoiceDesc1 = {
    Text = "[Бартер] Убрать 1 золотую реликвию, с вероятностью 50% получить 1 из 3 хрономаятников, с вероятностью 50% получить 1 из 3 благословенных реликвий"
  },
  Event_142120_ChoiceDesc2 = {
    Text = "\"покинуть\""
  },
  Event_142120_Desc = {
    Text = "Ты снова открываешь слепой бокс, но снова не находишь желаемого. Торговец торопливо улыбается и достаёт ещё одну железную коробку, протягивая её тебе обеими руками.\n«Не сердись, уважаемый! Клянусь, на этот раз там будет нечто невероятное...» — говорит он, но при этом незаметно убирает одну руку и раскрывает ладонь перед тобой. — «Конечно, сокровище нужно менять на сокровище.»"
  },
  Event_142120_Name = {
    Text = "Оборванный странствующий торговец"
  },
  Event_142138_ChoiceDesc1 = {
    Text = "[Воспользоваться]"
  },
  Event_142138_ChoiceDesc2 = {
    Text = "\"покинуть\""
  },
  Event_142138_Desc = {
    Text = "Тебе удалось воспользоваться этими инструментами. Они немного повреждены, но, кажется, ещё пригодны к использованию."
  },
  Event_142138_Name = {
    Text = "Кузница"
  },
  Event_142139_ChoiceDesc1 = {
    Text = "[Разбить и перелить] Выбрать 1 Золотую реликвию для удаления, получить 2 Серебряные реликвии и 50 Чёрных печатей"
  },
  Event_142139_ChoiceDesc2 = {
