  Event_91505_Desc = {
    Text = "Ты больше не борешься, позволяя крыльям и черной жидкости проникнуть в линии твоих ладоней. \n Ты стал его сосудом, а он, используя тебя как оболочку, продолжает размышлять. \n Бабочка становится все больше, и ты наконец не в силах выдержать вес. \n Увидев это, Доресайн с энтузиазмом разрезает связь между тобой и бабочкой своим обеденным ножом. Его нетерпеливый взгляд явно говорит о том, что он хочет... \n Ты отказал ему в просьбе."
