  Event_91507_Desc = {
    Text = "Ты закрываешь глаза и входишь в бесконечный, мягкий пыльный туман, облака звезд обнимают тебя, и ты теряешь свою форму, нечто более прочное, чем тело, оседает внутри тебя. \nВ ту ночь звёзды продолжали вращаться, как и прежде, ярко. \nЧто же означает ночное небо для бессмертных? Возможно, тебе стоит спросить Доресайн."
